import type { EditorPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import { tiptapExtensions } from './tiptap/tiptap.js';
import type { HashtagPluginEditorConfig } from './types.js';
import { HASHTAG_TYPE } from './types.js';

export const pluginHashtag: EditorPluginCreator<HashtagPluginEditorConfig> = config => {
  const pluginConfig = { type: 'hashtag' as const, ...DEFAULTS.config, ...config };
  return {
    config: pluginConfig,
    type: HASHTAG_TYPE,
    tiptapExtensions,
  };
};
