import React, { Suspense, lazy } from 'react';

const HeadingsPanelController = lazy(() =>
  import('./headings-dropdown.js').then(({ default: HeadingsDropdown }) => ({
    default: HeadingsDropdown,
  }))
);

const HeadingPanelComponent = (suspenseWidth: number) => () => (
  <Suspense fallback={<div style={{ width: suspenseWidth }} />}>
    <HeadingsPanelController minWidth={suspenseWidth} />
  </Suspense>
);

export default HeadingPanelComponent;
