import classNames from 'classnames';
import React from 'react';

import { SPOILER_CONTAINER } from './../../_shared/data-hooks.js';
import { debounce } from './../../_shared/debounce.js';

import styles from '../statics/styles/spoiler-scss.js';
import { SPOILER_TYPE } from '../types.js';
import { SpoilerContainer } from './spoiler-container.js';

const Overlay = ({ pluginType }: { pluginType?: string }) => (
  <div role="none" className={pluginType === 'Gallery' ? styles.overlay_gallery : styles.overlay} />
);

type Props = {
  componentData?: $TSFixMe;
  children?: React.ReactNode;
  theme?: $TSFixMe;
  disabledRevealSpoilerBtn?: boolean;
  isEditableText?: boolean;
  pluginType?: string;
  onClick?: (...args: $TSFixMe[]) => void;
  handleDescriptionChange?: (...args: $TSFixMe[]) => void;
  handleButtonContentChange?: (...args: $TSFixMe[]) => void;
  className?: string;
  setFocusToBlock?: (...args: $TSFixMe[]) => void;
  setInPluginEditingMode?: (...args: $TSFixMe[]) => void;
  width?: $TSFixMe;
  t: (key: string) => string;
  isMobile?: boolean;
  helpers?: $TSFixMe;
  type?: string;
};

type State = { isReveal?: boolean };

export class BlockSpoilerComponent extends React.Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {};
  }

  componentDidMount() {
    if (window?.ResizeObserver) {
      // @ts-expect-error
      this.resizeObserver = new ResizeObserver(debounce(this.onResizeElement, 60));
      // @ts-expect-error
      this.resizeObserver?.observe(this.elementRef);
    }
  }

  onResizeElement = () => {
    this.forceUpdate();
  };

  componentWillUnmount() {
    if (window?.ResizeObserver) {
      // @ts-expect-error
      this.resizeObserver?.unobserve(this.elementRef);
    }
  }

  handleClick = (e: $TSFixMe) => {
    const { onClick } = this.props;
    const { isReveal } = this.state;
    isReveal && onClick?.(e);
  };

  onRevealSpoiler = (e: $TSFixMe) => {
    const { helpers, pluginType } = this.props;
    e.preventDefault();
    this.setState({ isReveal: true });
    helpers.onViewerAction?.(SPOILER_TYPE, 'Click', `reveal_${pluginType}`);
  };

  renderSpoilerContainer = () => {
    const { isReveal } = this.state;
    const {
      disabledRevealSpoilerBtn,
      setFocusToBlock,
      componentData,
      pluginType,
      setInPluginEditingMode,
      handleButtonContentChange,
      handleDescriptionChange,
      isMobile,
      t,
      helpers,
    } = this.props;

    // @ts-expect-error
    const width = this.elementRef?.offsetWidth;
    // @ts-expect-error
    const height = this.elementRef?.offsetHeight;
    return (
      !isReveal && (
        <SpoilerContainer
          styles={styles}
          width={width}
          height={height}
          setInPluginEditingMode={setInPluginEditingMode}
          setFocusToBlock={setFocusToBlock}
          pluginType={pluginType}
          description={componentData?.config?.spoiler?.description}
          buttonContent={componentData?.config?.spoiler?.buttonContent}
          onRevealSpoiler={!disabledRevealSpoilerBtn ? this.onRevealSpoiler : undefined}
          handleButtonContentChange={handleButtonContentChange}
          handleDescriptionChange={handleDescriptionChange}
          isMobile={isMobile}
          t={t}
          helpers={helpers}
        />
      )
    );
  };

  onKeyDown = (e: $TSFixMe) => {
    if (e.key === 'Enter') {
      this.handleClick(e);
    }
  };

  setRef = (ref: $TSFixMe) =>
    // @ts-expect-error
    (this.elementRef = ref);

  render() {
    const { children, pluginType, width, isMobile } = this.props;
    const { isReveal } = this.state;
    let className = '';
    let blur = '';
    if (!isReveal) {
      const isGallery = pluginType === 'Gallery';
      className = isGallery ? styles.hideBlock_gallery : styles.hideBlock;
      if (!isGallery) {
        // @ts-expect-error
        const width = this.elementRef?.offsetWidth;
        blur = width < 400 ? styles.smallBlur : width < 700 ? styles.mediumBlur : styles.largeBlur;
      }
    }

    const inertAttributes = { inert: 'inert' } as React.HTMLAttributes<HTMLDivElement>;

    return (
      <div
        ref={this.setRef}
        className={classNames(styles.spoilerWrapper, this.props.className, {
          [styles.isMobile]: isMobile,
        })}
        style={{ width }}
        data-hook={SPOILER_CONTAINER}
      >
        {this.renderSpoilerContainer()}
        <div
          className={classNames(className, blur)}
          onClick={this.handleClick}
          role="button"
          tabIndex={0}
          onKeyDown={this.onKeyDown}
        >
          {isReveal ? (
            children
          ) : (
            <div {...inertAttributes}>
              {children}
              <Overlay pluginType={pluginType} />
            </div>
          )}
        </div>
      </div>
    );
  }
}
