import type {
  EditorPluginCreator,
  RicosExtensionConfig,
  RicosFunctionalExtension,
} from './../ricos-types/index.js';
import type { CollaborationOptions } from './../tiptap/extension-collaboration/index.js';
import { Collaboration } from './../tiptap/extension-collaboration/index.js';

const createRicosExtension = (options?: CollaborationOptions): RicosFunctionalExtension => ({
  type: 'extension',
  groups: [],
  name: 'collab',
  reconfigure(config: RicosExtensionConfig) {
    return config;
  },
  createExtensionConfig() {
    const extension = Collaboration.configure(options);

    return {
      ...extension.config,
      priority: Number.POSITIVE_INFINITY,
    };
  },
});

export const pluginCollab: EditorPluginCreator = (options?: CollaborationOptions) => ({
  type: 'extension',
  name: 'collab',
  config: {},
  tiptapExtensions: [createRicosExtension(options)],
});
