import type { PropsWithChildren } from 'react';
import React from 'react';

import type { RichContent } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';

export const EditorEvents = { PUBLISH: 'plugin:publish', RICOS_PUBLISH: 'ricos:publish' };

const defaultEditorEventsContextValue = {
  subscribe() {
    return () => {};
  },
  unsubscribe() {},
  dispatch() {
    return Promise.resolve(true);
  },
  publish() {
    return Promise.resolve({} as RichContent);
  },
};

export const EditorEventsContext = React.createContext(defaultEditorEventsContextValue);

export interface EditorEventsProps {
  editorEvents: EditorContextProps;
}

type EditorContextProps = Omit<EditorEventsProvider, keyof React.Component>;

export const withEditorEvents = (WrappedComponent: $TSFixMe) => (props: $TSFixMe) => (
  <EditorEventsContext.Consumer>
    {contextValue => <WrappedComponent editorEvents={contextValue} {...props} />}
  </EditorEventsContext.Consumer>
);

export class EditorEventsProvider extends React.Component<PropsWithChildren> {
  state = {
    subscribe: this.subscribe.bind(this),
    unsubscribe: this.unsubscribe.bind(this),
    dispatch: this.dispatch.bind(this),
    publish: this.publish.bind(this),
  };

  events: $TSFixMe = {};

  dispatch(event: $TSFixMe, data: $TSFixMe) {
    const callbacks = this.events[event] || [];
    return Promise.all(callbacks.map((cb: $TSFixMe) => cb(data)));
  }

  publish(): Promise<RichContent> {
    return this.dispatch(EditorEvents.PUBLISH, undefined).then(() => {
      return this.dispatch(EditorEvents.RICOS_PUBLISH, undefined).then(async publishResponse => {
        const editorResponse = publishResponse.filter(
          ({ type } = {}) => type === 'EDITOR_PUBLISH'
        )[0];
        return (editorResponse as Record<string, unknown>)?.data as RichContent;
      });
    });
  }

  subscribe(event: $TSFixMe, cb: $TSFixMe) {
    this.events[event] = this.events[event] || [];
    this.events[event].push(cb);

    return () => this.unsubscribe(event, cb);
  }

  unsubscribe(event: $TSFixMe, cb: $TSFixMe) {
    this.events[event] = (this.events[event] || []).filter((callback: $TSFixMe) => callback !== cb);
  }

  render() {
    const { children } = this.props;

    return (
      <EditorEventsContext.Provider value={this.state as $TSFixMe}>
        {children}
      </EditorEventsContext.Provider>
    );
  }
}

/**
 * Mounts an `EditorEventsProvider` unless the host app already provides one
 * (legacy hosts wrap the editor themselves and dispatch `publish` from outside).
 * The editor depends on this event bus internally: `prePublish()` dispatches
 * `plugin:publish` so plugins that sync with a server before the content is
 * read (e.g. polls) get a chance to run. Without a provider those hooks are
 * silent no-ops and published content ends up with unsynced plugin data.
 */
export const EditorEventsFallbackProvider: React.FC<PropsWithChildren> = ({ children }) => {
  const editorEvents = React.useContext(EditorEventsContext);
  const hasHostProvider = editorEvents !== defaultEditorEventsContextValue;

  return hasHostProvider ? (
    <>{children}</>
  ) : (
    <EditorEventsProvider>{children}</EditorEventsProvider>
  );
};

export const withEditorContext = (WrappedComponent: $TSFixMe) => {
  const WrappedComponentWithEvents = withEditorEvents(WrappedComponent);
  const withEditorProivder = (props: $TSFixMe) => {
    return (
      <EditorEventsProvider>
        <WrappedComponentWithEvents {...props} />
      </EditorEventsProvider>
    );
  };
  return withEditorProivder;
};
