import type { EditorPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './default-settings.js';
import { mentionConverter } from './mention-converter.js';
import { tiptapExtensions } from './tiptap/tiptap.js';
import type { MentionsPluginEditorConfig } from './types.js';
import { MENTION_TYPE } from './types.js';

export const pluginMentions: EditorPluginCreator<MentionsPluginEditorConfig> = config => {
  const pluginConfig = { ...DEFAULTS.config, ...config };
  return {
    config: pluginConfig,
    pmNodeConverters: [],
    pmMarkConverters: [mentionConverter],
    type: MENTION_TYPE,
    tiptapExtensions,
  };
};
