/* oxlint-disable jsx-a11y/no-static-element-interactions */
import { Box, Divider, InfoIcon, ListItemSelect } from '@wix/design-system';
import React, { useContext, useEffect, useRef } from 'react';

import { RicosContext, ZIndexContext } from './../../ricos-context/index.js';

import {
  HEADINGS_UPDATE_PANEL,
  HEADINGS_UPDATE_PANEL_APPLY,
  HEADINGS_UPDATE_PANEL_INFO_ICON,
  HEADINGS_UPDATE_PANEL_RESET,
  HEADINGS_UPDATE_PANEL_UPDATE,
} from '../data-hooks.js';
import classes from './headings-dropdown-scss.js';

export type UpdateHeadingPanelProps = {
  optionName: string;
  onApply: () => void;
  onMatchStyling: () => void;
  onReset: () => void;
  isUpdatedEnabled: () => boolean;
  isResetEnabled: () => boolean;
  /** ArrowLeft from any row: hands navigation back to the heading that owns this panel. */
  onNavigateBack: () => void;
  /**
   * Move focus to the first row on open, per the ARIA submenu pattern. Only a
   * keyboard open (ArrowRight) should pass true — a hover open must not steal
   * focus from wherever it currently is.
   */
  autoFocus?: boolean;
};

/**
 * WDS `ListItemSelect` accepts no keyboard props, so each row's activation
 * contract lives on a wrapper — the same element that carries `role="menuitem"`.
 * (WDS stamps `aria-disabled` on its own role-less root too; that copy is inert
 * to assistive tech and not suppressible via props.)
 * The rows are also the panel's only focusable elements, which is why ArrowLeft
 * is handled here rather than on the surface: a key pressed on a row never
 * reaches a handler further down the tree.
 *
 * Activation events stop propagating even when the row is disabled, so a row
 * never reads as an interaction with the option row this panel nests inside.
 * That row also refuses anything originating in the panel (`isFromUpdatePanel`),
 * which is what covers the panel's non-row areas — its padding band and the
 * divider strip — since WDS `Box` forwards no handlers to stop them here.
 */
const PanelRow: React.FC<{
  dataHook: string;
  title: string;
  suffix?: React.ReactNode;
  disabled?: boolean;
  onSelect: () => void;
  onNavigateBack: () => void;
  rowRef?: React.Ref<HTMLDivElement>;
}> = ({ dataHook, title, suffix, disabled = false, onSelect, onNavigateBack, rowRef }) => (
  <div
    ref={rowRef}
    role="menuitem"
    aria-disabled={disabled}
    tabIndex={disabled ? -1 : 0}
    onClick={e => {
      e.stopPropagation();
      if (!disabled) {
        onSelect();
      }
    }}
    onKeyDown={e => {
      if (e.key === 'ArrowLeft') {
        e.stopPropagation();
        e.preventDefault();
        onNavigateBack();
        return;
      }

      if (e.key === 'Enter' || e.key === ' ') {
        e.stopPropagation();
        e.preventDefault();
        if (!disabled) {
          onSelect();
        }
      }
    }}
  >
    <ListItemSelect
      dataHook={dataHook}
      size="small"
      title={title}
      suffix={suffix}
      disabled={disabled}
    />
  </div>
);

export const UpdateHeadingPanel: React.FC<UpdateHeadingPanelProps> = ({
  optionName,
  onApply,
  onMatchStyling,
  onReset,
  isUpdatedEnabled,
  isResetEnabled,
  onNavigateBack,
  autoFocus = false,
}) => {
  const { t, portal } = useContext(RicosContext);
  const zIndexService = useContext(ZIndexContext);

  // The apply row: first in the panel and never disabled. Depends on
  // `autoFocus` rather than running on mount only, so ArrowRight pressed while
  // the panel is already hover-open still moves focus in.
  const firstRowRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (autoFocus) {
      firstRowRef.current?.focus();
    }
  }, [autoFocus]);

  return (
    <Box
      direction="vertical"
      className={classes.panel}
      dataHook={HEADINGS_UPDATE_PANEL}
      role="menu"
    >
      <PanelRow
        dataHook={HEADINGS_UPDATE_PANEL_APPLY}
        title={t('FormattingToolbar_TextStyle_Heading_Apply', { optionName })}
        onSelect={onApply}
        onNavigateBack={onNavigateBack}
        rowRef={firstRowRef}
      />
      <div className={classes.divider}>
        <Divider />
      </div>
      <PanelRow
        dataHook={HEADINGS_UPDATE_PANEL_UPDATE}
        title={t('FormattingToolbar_TextStyle_Heading_Update', { optionName })}
        suffix={
          <div className={classes.infoIcon}>
            <InfoIcon
              dataHook={HEADINGS_UPDATE_PANEL_INFO_ICON}
              size="small"
              content={t('FormattingToolbar_TextStyle_Update_Heading_Tooltip', { optionName })}
              tooltipProps={{
                // The portal element itself, rather than a predicate that hunts for
                // it: WDS walks ancestors with `getParentNode`, which returns <html>
                // for <html>, so a predicate that never matches recurses forever.
                //
                // It has to be the portal and not the modal element, even though
                // the modal would share a containing block: the tooltip renders
                // beyond the modal's right edge, and inside it `max-width: 100%`
                // resolves against the modal's narrow box — measured 34px wide by
                // 720px tall.
                appendTo: portal ?? undefined,
                // The portal sits at body level, so WDS positions the tooltip in
                // document coordinates — but this trigger lives inside the modal,
                // which floating-ui places with `strategy: 'fixed'`, in viewport
                // coordinates. The two only agree while the page is unscrolled;
                // scrolled, the tooltip is pushed a scroll-height down the page and
                // off screen. `fixed` puts it on the same footing as the modal.
                fixed: true,
                zIndex: zIndexService.getZIndex('TOOLTIP'),
                size: 'small',
                enterDelay: 300,
              }}
            />
          </div>
        }
        onSelect={onMatchStyling}
        disabled={!isUpdatedEnabled()}
        onNavigateBack={onNavigateBack}
      />
      <PanelRow
        dataHook={HEADINGS_UPDATE_PANEL_RESET}
        title={t('FormattingToolbar_TextStyle_Heading_Reset')}
        onSelect={onReset}
        disabled={!isResetEnabled()}
        onNavigateBack={onNavigateBack}
      />
    </Box>
  );
};
