import {
  AlignBottom,
  AlignBottomSmall,
  AlignCenterHorizontally,
  AlignCenterHorizontallySmall,
  AlignTop,
  AlignTopSmall,
} from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { RicosContext } from './../../../../ricos-context/index.js';
import { DropdownModal } from './../../../../_shared/dropdown-modal/dropdown-modal.js';
import { ListItemSelect } from './../../../../_shared/list-item-select/list-item-select.js';

export const VERTICAL_ALIGNMENT_BUTTONS = {
  TOP: {
    commandKey: 'TOP',
    icon: AlignTop,
    iconSmall: AlignTopSmall,
    tooltip: 'Toolbar_VerticalAlignment_AlignTop_Tooltip',
    dataHook: 'vertical-alignment-align-top',
  },
  MIDDLE: {
    commandKey: 'MIDDLE',
    icon: AlignCenterHorizontally,
    iconSmall: AlignCenterHorizontallySmall,
    tooltip: 'Toolbar_VerticalAlignment_AlignMiddle_Tooltip',
    dataHook: 'vertical-alignment-align-middle',
  },
  BOTTOM: {
    commandKey: 'BOTTOM',
    icon: AlignBottom,
    iconSmall: AlignBottomSmall,
    tooltip: 'Toolbar_VerticalAlignment_AlignBottom_Tooltip',
    dataHook: 'vertical-alignment-align-bottom',
  },
} as const;

type Props = {
  dropdownOptions: {
    id: 'TOP' | 'MIDDLE' | 'BOTTOM';
    dataHook: string;
    label: string;
    icon: React.ComponentType;
    iconMobile: React.ComponentType;
  }[];
  onSelect: (value: 'TOP' | 'MIDDLE' | 'BOTTOM') => void;
  selectedId?: 'TOP' | 'MIDDLE' | 'BOTTOM';
  closeModal: () => void;
};

export const VerticalAlignmentDropdown: React.FC<Props> = ({
  dropdownOptions,
  onSelect,
  selectedId,
  closeModal,
}) => {
  const { t, isMobile } = useContext(RicosContext);

  return (
    <DropdownModal
      options={dropdownOptions.map(
        ({ dataHook, icon: Icon, iconMobile: IconMobile, id, label }) => (
          <ListItemSelect
            key={id}
            dataHook={dataHook}
            prefix={isMobile ? <IconMobile /> : <Icon />}
            selected={id === selectedId}
            onSelect={() => {
              onSelect(id);
              closeModal();
            }}
            title={t(label)}
          />
        )
      )}
      onCloseButtonClick={closeModal}
      title={t('TablePlugin_Toolbar_VerticalAlignment_Tooltip')}
    />
  );
};
