/* oxlint-disable jsx-a11y/no-static-element-interactions */
/* oxlint-disable jsx-a11y/mouse-events-have-key-events */
import { Box, ListItemSelect, SidePanel } from '@wix/design-system';
import { ChevronRight } from '@wix/wix-ui-icons-common/lazy';
import classNames from 'classnames';
import React, { useContext } from 'react';

import {
  EditorContext,
  ModalServiceContext,
  PluginsContext,
  RicosContext,
} from './../../ricos-context/index.js';
import type { HeadingType, TextBlockType } from './../../ricos-types/index.js';
import { DOC_STYLE_TYPES, Node_Type } from './../../ricos-types/index.js';
// `createDropdownModalUniDriver` scopes every option lookup to
// TOOLBAR_DROPDOWN_PANEL and then LIST_ITEM_SELECT, so the WDS composition below
// keeps rendering both — that is what leaves the shared headings testkit, and the
// legacy integration test built on it, working unchanged.
import { TOOLBAR_DROPDOWN_PANEL } from './../../_shared/dropdown-modal/data-hooks.js';
import { hasStyleChanges, translateHeading } from './../../_shared/headings-dropdown-utils.js';
import { isEmpty } from './../../_shared/is-empty.js';
import { LIST_ITEM_SELECT, LIST_ITEM_SELECT_SUFFIX } from './../../_shared/list-item-select/data-hooks.js';
import { dataHook } from './../../wix-rich-content-common/index.js';
import type { HeadingsPluginEditorConfig } from './../types.js';

import {
  HEADINGS_DROPDOWN_CHEVRON,
  HEADINGS_DROPDOWN_OPTION,
  HEADINGS_UPDATE_PANEL,
} from '../data-hooks.js';
import { ColorsIcon } from './colors-icon.js';
import classes from './headings-dropdown-scss.js';
import { UpdateHeadingPanel } from './update-heading-panel.js';

const HEADINGS_MODAL_ID = `${Node_Type.HEADING}.modal`;

export const DEFAULT_HEADERS_DROPDOWN_OPTIONS: Exclude<
  HeadingsPluginEditorConfig['customHeadings'],
  undefined
> = ['H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'P'];

export const HEADER_TYPE_MAP: Record<
  NonNullable<HeadingsPluginEditorConfig['customHeadings']>[number],
  TextBlockType
> = {
  H1: 'header-one',
  H2: 'header-two',
  H3: 'header-three',
  H4: 'header-four',
  H5: 'header-five',
  H6: 'header-six',
  P: 'unstyled',
};

export type HeadingsDropdownProps = {
  minWidth?: number;
};

/**
 * The update panel renders inside the option row that owns it, so every event
 * raised in the panel bubbles through the row's own handlers — which would read
 * it as picking that heading. The panel's rows stop their activation events, but
 * its surface cannot: WDS `Box` forwards no handlers at all, leaving its padding
 * band and the divider strip live. Testing the event's origin covers the whole
 * panel, whatever it grows to contain.
 */
const isFromUpdatePanel = (e: React.SyntheticEvent) =>
  !!(e.target as HTMLElement).closest(dataHook(HEADINGS_UPDATE_PANEL));

const HeadingsDropdown: React.FC<HeadingsDropdownProps> = ({ minWidth = 216 }) => {
  const { isMobile, t } = useContext(RicosContext);
  const { getPublicCommands } = useContext(EditorContext);
  const modalService = useContext(ModalServiceContext) || {};
  const plugins = useContext(PluginsContext);
  const headingsData = plugins?.getConfig(
    'wix-rich-content-plugin-headings'
  ) as HeadingsPluginEditorConfig;
  const allowHeadingCustomization = !!headingsData?.allowHeadingCustomization;

  // `viaKeyboard` decides whether the panel grabs focus on open: ArrowRight
  // follows the ARIA submenu pattern and moves focus to the panel's first row,
  // while a hover open must not steal focus from wherever it currently is.
  const [openOption, setOpenOption] = React.useState<{
    heading: HeadingType;
    viaKeyboard: boolean;
  } | null>(null);

  // The row that owns the open panel gets focus handed back when the panel
  // closes on ArrowLeft — the focused panel row unmounts, and without an
  // explicit hand-back the browser drops focus to `body`.
  const rowRefs = React.useRef<Partial<Record<string, HTMLDivElement | null>>>({});

  const publicCommands = getPublicCommands();
  const selectedHeading = publicCommands.getCurrentHeading();

  const closeModal = () => modalService.closeModal(HEADINGS_MODAL_ID);

  const handleOnSelect = (
    heading: NonNullable<HeadingsPluginEditorConfig['customHeadings']>[number]
  ) => {
    const headingType = HEADER_TYPE_MAP[heading];
    const shouldSetBlockType = selectedHeading !== headingType;
    shouldSetBlockType && publicCommands.setBlockType(headingType);
    closeModal();
  };

  // WDS ListItemSelect takes no rest props, so the row's keyboard and pointer
  // contract lives on the wrapper — which is also the element that carries
  // `role="option"` inside the surface's `role="listbox"`. WDS stamps
  // `aria-selected`/`aria-disabled` on its own role-less root too; those copies
  // are inert to assistive tech and not suppressible via props.
  const options = (headingsData?.customHeadings || DEFAULT_HEADERS_DROPDOWN_OPTIONS).map(
    heading => {
      const headerType = HEADER_TYPE_MAP[heading];
      const selected = selectedHeading === headerType;
      const optionName = translateHeading(heading, t);
      const size = isMobile ? 'medium' : 'small';

      const selectOnEnterOrSpace = (e: React.KeyboardEvent<HTMLDivElement>) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.stopPropagation();
          e.preventDefault();
          handleOnSelect(heading);
          return true;
        }
        return false;
      };

      if (!allowHeadingCustomization) {
        return (
          <div
            key={heading}
            className={classes.option}
            role="option"
            aria-selected={selected}
            tabIndex={0}
            onClick={() => handleOnSelect(heading)}
            onKeyDown={selectOnEnterOrSpace}
          >
            <ListItemSelect size={size} title={optionName} selected={selected} />
          </div>
        );
      }

      const documentStyleType = DOC_STYLE_TYPES[heading];
      const optionWiredStyles = publicCommands.getWiredFontStyles()?.[
        documentStyleType
      ] as unknown as Record<string, string>;
      const subtitle = optionWiredStyles?.['font-size'] ?? '16px';
      const fontFamily = optionWiredStyles?.['font-family'] ?? 'inherit';

      return (
        <div
          key={heading}
          ref={el => {
            rowRefs.current[heading] = el;
          }}
          className={classes.option}
          role="option"
          aria-selected={selected}
          tabIndex={0}
          onClick={e => {
            if (isFromUpdatePanel(e)) {
              return;
            }

            handleOnSelect(heading);
          }}
          onKeyDown={e => {
            if (isFromUpdatePanel(e) || selectOnEnterOrSpace(e)) {
              return;
            }

            if (e.key === 'ArrowRight') {
              e.stopPropagation();
              e.preventDefault();
              setOpenOption({ heading, viaKeyboard: true });
            }
          }}
          onMouseOver={e => {
            if (isFromUpdatePanel(e)) {
              return;
            }

            const target = e.target as HTMLElement;
            // The whole suffix slot, not just the chevron glyph inside it: the slot
            // is stretched to the row's height so the hover target is the full
            // column, and the chevron is only what it renders.
            const isChevronColumn = target.closest(dataHook(LIST_ITEM_SELECT_SUFFIX));
            if (isChevronColumn) {
              // Guarded because an object doesn't get the setState bail-out an
              // identical string did — mouseover would re-render on every move.
              if (openOption?.heading !== heading) {
                setOpenOption({ heading, viaKeyboard: false });
              }
              return;
            }

            if (openOption?.heading !== heading) {
              setOpenOption(null);
            }
          }}
        >
          <ListItemSelect
            dataHook={classNames(LIST_ITEM_SELECT, HEADINGS_DROPDOWN_OPTION)}
            size={size}
            selected={selected}
            prefix={
              <ColorsIcon
                color={optionWiredStyles?.color}
                backgroundColor={optionWiredStyles?.['background-color']}
              />
            }
            subtitle={subtitle}
            title={<span style={{ fontFamily }}>{optionName}</span>}
            suffix={isMobile ? null : <ChevronRight data-hook={HEADINGS_DROPDOWN_CHEVRON} />}
          />
          {openOption?.heading === heading && (
            <UpdateHeadingPanel
              autoFocus={openOption?.viaKeyboard}
              optionName={optionName}
              onApply={() => handleOnSelect(heading)}
              onMatchStyling={() => {
                publicCommands.updateDocumentStyle({});
                closeModal();
              }}
              onReset={() => {
                publicCommands.resetDocumentStyleByNodeType(documentStyleType);
                closeModal();
              }}
              isUpdatedEnabled={() => {
                const currentInlineStyles = publicCommands.getInlineStylesInSelection();
                const documentStyle = publicCommands.getDocumentStyle();

                return (
                  headerType === selectedHeading &&
                  hasStyleChanges(selectedHeading, currentInlineStyles, documentStyle)
                );
              }}
              isResetEnabled={() => {
                const documentStyle = publicCommands.getDocumentStyle();
                return !isEmpty(documentStyle?.[documentStyleType]);
              }}
              onNavigateBack={() => {
                setOpenOption(null);
                // Synchronous, so focus lands before React unmounts the panel
                // row that currently holds it.
                rowRefs.current[heading]?.focus();
              }}
            />
          )}
        </div>
      );
    }
  );

  if (isMobile) {
    return (
      <SidePanel
        closeButtonProps={{ onClick: closeModal }}
        width="100%"
        maxHeight="50vh"
        height="fit-content"
      >
        <SidePanel.Header title={t('HeadingsDropdown_Title')} />
        <SidePanel.Content className={classes.mobileContent}>
          <div role="listbox">{options}</div>
        </SidePanel.Content>
      </SidePanel>
    );
  }

  return (
    <Box
      direction="vertical"
      className={classes.dropdown}
      dataHook={TOOLBAR_DROPDOWN_PANEL}
      role="listbox"
      minWidth={`${minWidth}px`}
    >
      {options}
    </Box>
  );
};

// oxlint-disable-next-line import/no-default-export
export default HeadingsDropdown;
