import classNames from 'classnames';
import React, { useContext, useEffect } from 'react';

import { useConverters } from './../../pm-converters/context.js';
import {
  PluginsEventsContext,
  RicosContext,
  usePluginExportsContext,
} from './../../ricos-context/index.js';
import type { ImageNode } from './../../ricos-schema/next-schema/index.js';
import type { PluginProps } from './../../ricos-types/index.js';
import { Node_Type } from './../../ricos-types/index.js';
import { isNodeSelected } from './../../_shared/is-node-selected.js';
import { normalizeLineHeight } from './../../_shared/line-spacing-utils.js';
import { getPluginContainerClassNames, getPluginFocusClassNames } from './../../_shared/node-styles.js';

import { CAPTION } from '../data-hooks.js';
import classes from './caption-scss.js';
import { useEditorSelection } from './use-editor-selection.js';

export const Caption: React.FC<PluginProps> = ({ NodeViewContent, editor, node, getPos }) => {
  const { isMobile } = useContext(RicosContext);
  const pluginsEvents = useContext(PluginsEventsContext);
  const pluginExports = usePluginExportsContext();
  const selectedNodes = useEditorSelection(editor).selectedNodes;
  const converters = useConverters();

  const captionPos = getPos();
  const doc = editor.state.doc;
  const $pos = doc.resolve(captionPos);
  const parentNode = $pos.parent ?? null;

  if (!parentNode) {
    console.error('Caption must have a parent.');
    return null;
  }
  const ricosParentNode = converters.fromPmNode(parentNode.toJSON());

  const AiButton = pluginExports.aiIntegrations?.image?.captionTrigger;

  const isCaptionSelected = selectedNodes.find(
    selectedNode => selectedNode.attrs.id === node.attrs?.id
  );
  const isParentSelected = selectedNodes.find(
    selectedNode => selectedNode.attrs.id === ricosParentNode?.id
  );

  useEffect(() => {
    if (node.content.firstChild?.text || isCaptionSelected || isParentSelected) {
      return;
    }
    pluginsEvents?.publishPluginLayoutShift({ nodeId: node.attrs.id });
  }, [isCaptionSelected, isParentSelected]);

  // Handle caption activation and cleanup
  useEffect(() => {
    const hasContent = !!node.content.firstChild?.text;
    const { showEmpty } = node.attrs;
    const { selection } = editor.state;

    const isMultiNodeSelection =
      !selection.empty && selection.$from.parent !== selection.$to.parent;

    if (isMultiNodeSelection) {
      return;
    }

    if (!isCaptionSelected && (!showEmpty || hasContent)) {
      return;
    }

    if (captionPos === null) {
      return;
    }

    const { tr } = editor.state;
    const nodePos = captionPos - 1;

    // Caption with content becomes selected (e.g. after refresh) -> set showEmpty to true
    if (isCaptionSelected && hasContent && !showEmpty) {
      tr.setNodeAttribute(nodePos, 'showEmpty', true);
      editor.view.dispatch(tr);
      return;
    }

    // Empty caption loses focus -> set showEmpty to false
    if (!isCaptionSelected && showEmpty && !hasContent) {
      tr.setNodeAttribute(nodePos, 'showEmpty', false);
      editor.view.dispatch(tr);
    }
  }, [captionPos, isCaptionSelected, node.content.firstChild?.text]);

  const isVisible = !!node.content.firstChild || node.attrs.showEmpty;
  const hasAiButton = isCaptionSelected && ricosParentNode?.type === Node_Type.IMAGE && AiButton;

  const isFocused = isNodeSelected(editor.state, node.attrs.id);

  const className = classNames(
    classes.caption,
    getPluginContainerClassNames(isMobile),
    getPluginFocusClassNames(isFocused)
  );

  /*
   * Display none is crucial here to prevent issues in older browser versions, specifically Chrome 113, which is used
   * in the Mobile App WebView. Adding new HTML elements to the DOM trigger ProseMirror's readDOMChange function,
   * causing it to misinterpret the update as a user action (e.g. pressing Enter) which triggers keyboard shortcuts.
   * https://github.com/ProseMirror/prosemirror-view/blob/f37ebb29befdbde3cd194fe13fe17b78e743d2f2/src/domchange.ts#L127
   * By setting display: 'none', we ensure the component remains in the DOM without being visually rendered
   * avoiding ProseMirror's DOM change detection.
   */

  return (
    <div
      className={className}
      style={
        isVisible
          ? undefined
          : {
              display: 'none',
            }
      }
    >
      {hasAiButton ? (
        <div className={classes.aiButtonContainer}>
          <AiButton
            node={ricosParentNode as ImageNode}
            onCaptionChange={caption => {
              if (captionPos === null) {
                return;
              }

              const { state } = editor;
              const captionNode = state.doc.nodeAt(captionPos);

              if (!captionNode) {
                return;
              }

              const from = captionPos + 1;
              const to = captionPos + captionNode.nodeSize - 1;
              const { tr } = state;

              tr.insertText(caption, from, to);
              editor.view.dispatch(tr);
            }}
          />
        </div>
      ) : null}
      <NodeViewContent
        dir="auto"
        data-hook={CAPTION}
        as="figcaption"
        style={{
          width: '100%',
          overflow: 'auto',
          ...(node.attrs?.textStyle?.lineHeight && {
            lineHeight: normalizeLineHeight(node.attrs?.textStyle?.lineHeight),
          }),
          textAlign: node.attrs?.textStyle?.textAlignment,
          paddingTop: node.attrs?.style?.paddingTop ?? node.attrs?.styleDefaults?.paddingTop,
          paddingBottom:
            node.attrs?.style?.paddingBottom ?? node.attrs?.styleDefaults?.paddingBottom,
        }}
      />
    </div>
  );
};
