import React, { useContext } from 'react';

import { useBiCallbacks } from './../../../_shared/bi-helpers-context/bi-helpers-context.js';
import { GlobalContext } from './../../../wix-rich-content-common/index.js';

import { BlockSpoilerComponent } from '../block-spoiler-component.js';

export const SpoilerViewerWrapper: React.FC<$TSFixMe> = props => {
  const { componentData, type, children } = props;
  const hasSpoiler = componentData?.config?.spoiler?.enabled || false;
  const { isMobile, t } = useContext(GlobalContext) as { isMobile: boolean; t: $TSFixMe };
  const helpers = useBiCallbacks();

  if (!hasSpoiler) {
    return children;
  }

  const pluginType = type.toLowerCase().replace(/^./, (c: string) => c.toUpperCase());

  return (
    <BlockSpoilerComponent
      pluginType={pluginType}
      isMobile={isMobile}
      t={t}
      {...props}
      helpers={helpers}
    >
      {children}
    </BlockSpoilerComponent>
  );
};
