import type { NodeWithPos } from './../../tiptap/index.js';
import type { Node } from './../../tiptap/pm/model.js';

// Adjusted for figure and caption nodes
export const findAdjustedNodeById = (doc: Node, id: string): NodeWithPos | undefined => {
  const nodesWithPos: NodeWithPos[] = [];
  doc.descendants((child, pos) => {
    if (child.attrs.id === id) {
      nodesWithPos.push({
        node: child,
        pos,
      });
      return false;
    }
  });
  const nodeWithPos = nodesWithPos[0];
  if (!nodeWithPos) {
    return undefined;
  }
  const parent = doc.resolve(nodeWithPos.pos).parent;
  if (parent.type.name === 'FIGURE' && nodeWithPos.node.type.name !== 'CAPTION') {
    return { node: parent, pos: nodeWithPos.pos - 1 };
  }
  return nodeWithPos;
};
