/* oxlint-disable jsx-a11y/click-events-have-key-events */
import { Tooltip } from '@wix/design-system';
import { ChevronDownSmall } from '@wix/wix-ui-icons-common/lazy';
import cx from 'classnames';
import React, { useContext, useEffect, useRef, useState } from 'react';

import { RICOS_FONT_SIZE_TYPE } from './../../../../ricos-content/index.js';
import { EditorContext, RicosContext } from './../../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem, PublicCommands } from './../../../../ricos-types/index.js';
import { Decoration_Type } from './../../../../ricos-types/index.js';

import styles from './FontSizeButton-scss.js';

const MAX_FONT_SIZE = 900;
const MIN_FONT_SIZE = 1;

const onInputChange = (
  e: React.ChangeEvent<HTMLInputElement>,
  setInputValue: React.Dispatch<React.SetStateAction<string | number>>,
  publicCommands: PublicCommands
) => {
  const { value } = e.target;
  if (value === '') {
    // A cleared input is a mid-edit state — don't commit a decoration for it.
    setInputValue('');
    return;
  }
  const valueAsNumber = Number.parseInt(value);
  if (!valueAsNumber) {
    return;
  }
  setFontSize(valueAsNumber, setInputValue, publicCommands);
};

const setFontSize = (
  valueAsNumber: number,
  setInputValue: React.Dispatch<React.SetStateAction<string | number>>,
  publicCommands: PublicCommands
) => {
  setInputValue(Number.isNaN(valueAsNumber) ? '' : valueAsNumber);
  const fontSize = Math.min(Math.max(MIN_FONT_SIZE, valueAsNumber), MAX_FONT_SIZE);
  publicCommands.insertDecoration(RICOS_FONT_SIZE_TYPE, { fontSize: `${fontSize}` });
};

export const FontSizeButton: React.FC<{
  toolbarItem: IToolbarItem;
  dataHook?: string;
}> = ({ toolbarItem, dataHook }) => {
  const { t } = useContext(RicosContext);
  const { getPublicCommands } = useContext(EditorContext);
  const inputRef = useRef<HTMLInputElement>(null);
  // Armed on focus so only the click that granted focus select-alls; later clicks place the caret.
  const selectOnClickRef = useRef(false);
  const [referenceElement, setReferenceElement] = useState<HTMLDivElement | null>(null);
  const [inputValue, setInputValue] = useState<number | string>('');
  const publicCommands = getPublicCommands?.();
  const isModalOpen = useModalState(getIsModalOpen(`${Decoration_Type.FONT_SIZE}.modal`));

  const selectedFontSize: string = toolbarItem.attributes.selectedFontSize;

  useEffect(() => {
    setInputValue(selectedFontSize);
  }, [selectedFontSize]);

  const disabled = toolbarItem.attributes.disabled;
  const tooltip = t(toolbarItem.presentation?.tooltip);

  const handleClick = () =>
    toolbarItem.commands?.click({ referenceElement, focusReturnElement: inputRef.current });

  const handleWrapperClick = (e: React.MouseEvent) => {
    // A click inside the input while the presets are open is caret placement, not a toggle —
    // closing here would also return focus to the editor and send further keystrokes into it.
    if (isModalOpen && e.target === inputRef.current) {
      return;
    }
    handleClick();
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    // Once the user types, a following click is caret placement — don't re-select the value.
    selectOnClickRef.current = false;
    const currentFontSize = parseInt(selectedFontSize, 10);

    if (e.key === 'ArrowUp') {
      e.preventDefault();
      if (Number.isNaN(currentFontSize)) {
        return;
      }
      const newFontSize = Math.min(currentFontSize + 1, MAX_FONT_SIZE);
      setFontSize(newFontSize, setInputValue, publicCommands);
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      if (Number.isNaN(currentFontSize)) {
        return;
      }
      const newFontSize = Math.max(currentFontSize - 1, MIN_FONT_SIZE);
      setFontSize(newFontSize, setInputValue, publicCommands);
    } else if (e.key === 'Enter') {
      e.preventDefault();
      handleClick();
    }
  };

  return (
    <Tooltip key={tooltip} content={tooltip} size="small" moveBy={{ y: 8 }}>
      <div
        className={cx(styles.fontSizeButton, {
          [styles.active]: isModalOpen,
          [styles.disabled]: disabled,
        })}
        ref={setReferenceElement}
      >
        <div
          data-hook={dataHook}
          className={styles.fontSizeModalButton}
          role="button"
          onClick={handleWrapperClick}
          onKeyDown={handleKeyDown}
          tabIndex={-1}
          data-avoid-focus
        >
          <input
            aria-label={t('FormattingToolbar_CustomFontSizeButton_Tooltip')}
            className={styles.fontSizeModalInputButton}
            required
            value={inputValue}
            onChange={e => onInputChange(e, setInputValue, publicCommands)}
            onFocus={() => {
              // Select immediately for keyboard focus; a mouse click collapses this selection on
              // mouseup, so also arm the click handler to re-select once.
              inputRef.current?.select();
              selectOnClickRef.current = true;
            }}
            onClick={() => {
              if (selectOnClickRef.current) {
                selectOnClickRef.current = false;
                inputRef.current?.select();
              }
            }}
            ref={inputRef}
            tabIndex={toolbarItem.presentation.tabIndex}
          />
          <ChevronDownSmall />
        </div>
      </div>
    </Tooltip>
  );
};
