import { Decoration_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import mentionDataDefaults from './../../ricos-schema/legacy/statics/mention.defaults.json.js';
import type {
  DOMOutputSpec,
  ExtensionProps,
  MarkConfig,
  RicosExtension,
} from './../../ricos-types/index.js';
import type { Editor } from './../../tiptap/core/index.js';
import type { Node as ProseMirrorNode } from './../../tiptap/pm/model.js';
import { Fragment } from './../../tiptap/pm/model.js';
import type { SuggestionOptions } from './../../tiptap/suggestion/index.js';
import { createRicosMarkExtension } from './../../plugin-commons/index.js';

import styles from '../statics/mentions-scss.js';
import type { Mention, MentionsPluginEditorConfig } from '../types.js';
import { Suggestion } from './suggestion.js';

export type MentionOptions = {
  HTMLAttributes: Record<string, any>;
  renderLabel: (props: { options: MentionOptions; node: ProseMirrorNode }) => string;
  suggestion: Omit<SuggestionOptions, 'editor'>;
};

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    mention: {
      /**
       * Add text with mention mark
       */
      insertMention: (attributes: Mention, pos?: { from: number; to: number }) => ReturnType;
    };
  }
}

const findMention = (editor: Editor, char: string) => {
  const mentionRegex = new RegExp(`(?:^)?${char}[^\\s${char}]*`, 'gm');
  const { nodeBefore, pos } = editor.state.selection.$from;
  const { text, nodeSize: nodeBeforeSize } = nodeBefore || {};
  const mention = text?.match(mentionRegex)?.[0];
  const mentionIndex: number = text ? text.search(mentionRegex) : -1;
  if (nodeBeforeSize && mention && mentionIndex !== -1) {
    return { from: pos - nodeBeforeSize + mentionIndex, to: pos };
  }
};

export const tiptapExtensions = [
  createRicosMarkExtension({
    type: 'mark',
    groups: ['shortcuts-enabled'],
    name: Decoration_Type.MENTION,
    reconfigure: (
      config: MarkConfig,
      _extensions: RicosExtension[],
      _props: ExtensionProps,
      settings
    ) => {
      return {
        ...config,
        addOptions: () => ({
          settings,
          HTMLAttributes: {},
          renderLabel({ node }: { node: ProseMirrorNode }) {
            return `${(settings as unknown as MentionsPluginEditorConfig).mentionTrigger}${
              node.attrs.label ?? node.attrs.id
            }`;
          },
        }),
      };
    },

    createExtensionConfig() {
      return {
        priority: 110,
        name: this.name,

        group: 'inline',

        inline: true,

        selectable: false,

        atom: true,

        addAttributes() {
          return mentionDataDefaults.mentionData;
        },

        renderHTML() {
          return ['span', { class: styles.mention }, 0] as DOMOutputSpec;
        },

        addKeyboardShortcuts() {
          return {
            Backspace: () =>
              this.editor.commands.command(({ dispatch, tr, state }) => {
                let isMention = false;
                const { selection } = state;
                const { empty, anchor } = selection;

                if (!empty) {
                  return false;
                }

                state.doc.nodesBetween(anchor - 1, anchor, (node, pos) => {
                  if (node.text === this.options.settings.mentionTrigger) {
                    isMention = true;
                    dispatch?.(tr.replaceWith(pos, pos + 1, Fragment.empty));
                  }
                });

                return isMention;
              }),
          };
        },

        addProseMirrorPlugins() {
          return [Suggestion(this.editor, this.options.settings)];
        },

        addCommands() {
          return {
            insertMention:
              (mention, pos) =>
              ({ view, tr, editor }) => {
                // increase range.to by one when the next node is of type "text"
                // and starts with a space character
                const nodeAfter = view.state.selection.$to.nodeAfter;
                const overrideSpace = nodeAfter?.text?.startsWith(' ');
                const { mentionTrigger } = this.options.settings as MentionsPluginEditorConfig;
                const range = pos ||
                  (mentionTrigger && findMention(editor, mentionTrigger)) || {
                    from: tr.selection.from,
                    to: tr.selection.to,
                  };

                if (overrideSpace) {
                  range.to += 1;
                }

                return editor
                  .chain()
                  .focus()
                  .insertContentAt(range, [
                    {
                      type: 'text',
                      text: `${mentionTrigger}${mention.name}`,
                      marks: [
                        {
                          type: Decoration_Type.MENTION,
                          attrs: {
                            name: mention.name,
                            slug: mention.slug,
                            id: mention.id,
                            type: mention.type,
                          },
                        },
                      ],
                    },
                    {
                      type: 'text',
                      text: ' ',
                    },
                  ])
                  .run();
              },
          };
        },
      };
    },
  }),
];
