import { Objects } from '@wix/wix-ui-icons-common/lazy';

import type { PluginServices } from './../../ricos-plugins/editor-plugins.js';
import { Node_Type, type QuickAction, quickActionsModalSections } from './../../ricos-types/index.js';
import { ICONS_CATEGORY_ID } from './../../_shared/shape-select-modal/consts.js';
import type { ShapesCategoryId } from './../../_shared/shape-select-modal/types.js';
import { posToDOMRect } from './../../tiptap/index.js';
import type { ShapePluginEditorConfig } from './../utils/types.js';

import { ShapeSelectModal } from '../components/shape-select-modal.js';
import { SHAPE_SELECT_MODAL } from '../utils/data-hooks.js';

export const getQuickActions = (
  config: ShapePluginEditorConfig,
  pluginServices: PluginServices
): QuickAction[] => {
  const createCommand =
    (initialCategoryId?: ShapesCategoryId): QuickAction['command'] =>
    ({ modalService, editor, referenceElement }) => {
      modalService.togglePluginPanel({
        id: SHAPE_SELECT_MODAL,
        Component: ShapeSelectModal,
        componentProps: {
          getShapeUrl: config.getShapeUrl,
          initialCategoryId,
        },
        isMobile: pluginServices.context.isMobile,
        positioning: {
          referenceElement: referenceElement ?? {
            getBoundingClientRect: () =>
              posToDOMRect(
                editor.view,
                editor.view.state.selection.from,
                editor.view.state.selection.to
              ),
          },
          placement: 'bottom-start',
        },
      });
    };

  return [
    {
      id: Node_Type.SHAPE,
      title: 'ShapePlugin_QuickAction_Title',
      icon: Objects,
      section: quickActionsModalSections.Media,
      tags: ['shape', 'vector'],
      command: createCommand(),
    },
    {
      id: `${Node_Type.SHAPE}.icons`,
      title: 'ShapePlugin_QuickAction_Title_Icons',
      icon: Objects,
      section: quickActionsModalSections.Media,
      tags: ['icon', 'icons', 'symbol', 'pictogram', 'glyph'],
      command: createCommand(ICONS_CATEGORY_ID),
    },
  ];
};
