import React, { useContext } from 'react';
import type { INode } from 'svgson';

import { SHAPE_TYPE } from './../../ricos-content/index.js';
import { RicosViewerContext } from './../../ricos-context/index.js';
import type { Node } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { ShapeNode } from './../../ricos-schema/next-schema/index.js';
import { ShapeViewRenderer } from './../../_shared/shape-view-renderer.js';
import type {
  ShapeNodeViewRendererProps,
  ShapePluginEditorConfig,
} from './../utils/types.js';

import { RICOS_DEFAULTS } from '../utils/consts.js';
type Dimensions = {
  width: number;
  height: number;
};

type ShapeViewerProps = {
  node: ShapeNode;
  isLoading?: boolean;
  shapeJson?: INode;
  getShapeUrl?: ShapePluginEditorConfig['getShapeUrl'];
  dimensions?: Dimensions;
  onShapeLoaded?: (dimensions: { width: number; height: number }) => void;
};

const ShapeComponent = ({
  node,
  shapeJson,
  getShapeUrl,
  isLoading,
  dimensions,
  onShapeLoaded,
}: ShapeViewerProps) => {
  const { shape, containerData, styles } = node.shapeData;

  const customWidth = containerData?.width?.custom;

  return (
    <ShapeViewRenderer
      shapeJson={shapeJson}
      shapeSrc={shape.src}
      colors={styles?.colors}
      getShapeUrl={getShapeUrl}
      isLoading={isLoading}
      dimensions={dimensions}
      style={
        {
          '--ricos-internal-shape-width': customWidth,
        } as React.CSSProperties
      }
      onShapeLoaded={onShapeLoaded}
    />
  );
};

const ViewerShapeComponent = ({
  node,
  nodeIndex,
  NodeViewContainer,
  shapeJson,
  isLoading,
}: ShapeNodeViewRendererProps) => {
  const { config } = useContext(RicosViewerContext);
  const shapeConfig = config[SHAPE_TYPE] || {};
  const shapeNode = node as ShapeNode;

  const shapeDataWithDefaults = {
    ...shapeNode.shapeData,
    containerData: shapeNode.shapeData.containerData || RICOS_DEFAULTS.containerData,
  };

  const nodeWithDefaults = {
    ...node,
    shapeData: shapeDataWithDefaults,
  } as Node;

  return (
    <NodeViewContainer key={node.id} node={nodeWithDefaults} nodeIndex={nodeIndex}>
      {/* function-children form so the link wrapper sits inside the sized container
          and hugs the shape, instead of spanning the full node width */}
      {({ ContainerElement, LinkWrapper }) => (
        <ContainerElement>
          <LinkWrapper>
            <ShapeComponent
              node={nodeWithDefaults as ShapeNode}
              shapeJson={shapeJson}
              getShapeUrl={shapeConfig.getShapeUrl}
              isLoading={isLoading}
            />
          </LinkWrapper>
        </ContainerElement>
      )}
    </NodeViewContainer>
  );
};

export default ViewerShapeComponent;

export { ShapeComponent as Shape, ShapeViewRenderer };
