/* oxlint-disable jsx-a11y/no-static-element-interactions */
import type { ReactElement } from 'react';
import React, { Suspense } from 'react';

import { GlobalContext } from '../Utils/contexts.js';
import { getTooltipStyles } from './tooltip-styles.js';

declare global {
  interface Window {
    richContentHideTooltips: boolean;
  }
}

interface Props {
  content?: React.ReactNode;
  tooltipOffset?: { x: number; y: number };
  children: ReactElement;
  isError?: boolean;
  place?: 'top' | 'bottom' | 'left' | 'right';
  followMouse?: boolean;
  hideArrow?: boolean;
  forceVisibility?: boolean;
}

const lazyWithPreload = (factory: () => Promise<any>) => {
  const Component: any = React.lazy(factory);
  Component.preload = factory;
  return Component;
};

const ToolTipComponent = lazyWithPreload(async () => {
  const result = await import(
    /* webpackChunkName: "react-portal-tooltip" */
    'react-portal-tooltip'
  );
  // for esbuild consumers building esm bundle https://github.com/evanw/esbuild/issues/566#issuecomment-846707879 commonjs lazy chunks get double wrapped
  return (result.default as any)?.default ? result.default : result;
});

export class Tooltip extends React.Component<Props> {
  static defaultProps = {
    isError: false,
    place: 'top',
    tooltipOffset: { x: 0, y: 0 },
  };

  disabled = false;

  mousePosition: { x: number; y: number } = { x: 0, y: 0 };

  timeoutId!: NodeJS.Timeout;

  state = {
    tooltipVisible: false,
  };

  static contextType = GlobalContext;

  declare context: React.ContextType<typeof GlobalContext>;

  componentDidUpdate() {
    this.disabled = window.richContentHideTooltips; //used to hide tooltips in tests
  }

  componentWillUnmount() {
    clearTimeout(this.timeoutId);
  }

  showTooltip = (e: MouseEvent) => {
    ToolTipComponent.preload();
    if (!(e.target as HTMLButtonElement).disabled) {
      this.mousePosition = { x: e.pageX, y: e.pageY };

      this.timeoutId = setTimeout(() => {
        this.setState({ tooltipVisible: true }, () => {
          this.forceUpdate();
          setTimeout(() => this.props.followMouse && this.updateTooltipPosition());
        });
      }, 300);
    }
  };

  onMouseMove = (e: MouseEvent) => {
    if (this.props.followMouse) {
      this.mousePosition = { x: e.pageX, y: e.pageY };
      this.updateTooltipPosition();
    }
  };

  updateTooltipPosition = () => {
    const { x, y } = this.mousePosition;
    const element = document.querySelector<HTMLElement>('.ToolTipPortal > div');
    if (element) {
      const { offsetWidth: width, offsetHeight: height } = element;
      element.style.left = `${x - width / 2}px`;
      element.style.top = `${y - height - 25}px`;
    }
  };

  hideTooltip = () => {
    clearTimeout(this.timeoutId);
    this.setState({ tooltipVisible: false });
  };

  wrappChildrenProp = (propName: string, func: (e: MouseEvent) => void) => {
    return {
      [propName]: (e: $TSFixMe) => {
        func(e);
        this.props.children.props[propName]?.(e);
      },
    };
  };

  wrapperProps = {
    ...this.wrappChildrenProp('onMouseEnter', this.showTooltip),
    ...this.wrappChildrenProp('onMouseLeave', this.hideTooltip),
    ...this.wrappChildrenProp('onClick', this.hideTooltip),
    ...this.wrappChildrenProp('onMouseMove', this.onMouseMove),
  };

  render() {
    const {
      children,
      content,
      isError,
      place,
      tooltipOffset,
      followMouse,
      hideArrow,
      forceVisibility,
    } = this.props;
    const { tooltipVisible } = this.state;
    const { isMobile } = this.context;
    const style = getTooltipStyles(isError, followMouse, tooltipOffset, place);

    const elementProps =
      forceVisibility || tooltipVisible
        ? { ...this.wrapperProps, 'data-tooltipid': true }
        : this.wrapperProps;

    const tooltipArrow = hideArrow ? null : 'center';
    return isMobile || this.disabled || !content ? (
      children
    ) : (
      <>
        {React.cloneElement(React.Children.only(children), elementProps)}
        {forceVisibility || tooltipVisible ? (
          <Suspense fallback={null}>
            <ToolTipComponent
              active={forceVisibility || tooltipVisible}
              parent={'[data-tooltipid=true]'}
              position={place}
              arrow={tooltipArrow}
              style={style}
              tooltipTimeout={10}
              group={'ricos'}
            >
              {content}
            </ToolTipComponent>
          </Suspense>
        ) : null}
      </>
    );
  }
}
