import type { EditorPluginCreator } from './../ricos-types/index.js';

import { SpoilerEditorWrapper } from './Components/Wrappers/spoiler-editor-wrapper.js';
import { DEFAULTS } from './defaults.js';
import { getTextButtons } from './get-text-buttons.js';
import { spoilerConverter } from './spoiler-converter.js';
import { tiptapExtensions } from './tiptap/tiptap.js';
import type { SpoilerPluginEditorConfig } from './types.js';
import { SPOILER_TYPE } from './types.js';

export { SpoilerEditorWrapper };

export const pluginSpoiler: EditorPluginCreator<SpoilerPluginEditorConfig> = config => {
  const pluginConfig = {
    type: 'spoiler' as const,
    ...DEFAULTS.config,
    SpoilerEditorWrapper,
    ...config,
  };
  return {
    config: pluginConfig,
    pmNodeConverters: [],
    pmMarkConverters: [spoilerConverter],
    type: SPOILER_TYPE,
    tiptapExtensions,
    textButtons: getTextButtons(),
  };
};
