import type React from 'react';
import { useCallback } from 'react';

import { useConverters } from './../pm-converters/context.js';
import { generateId } from './../ricos-content/index.js';
import { debounce } from './../_shared/debounce.js';
import { useRequestService } from './../_shared/request-service-provider/request-service-provider.js';
import type { Transaction } from './../tiptap/pm/state.js';

import type { AiContentSuggestion, SuggestionsState } from './types.js';

export const useSuggestionsRequest = (
  setState: React.Dispatch<React.SetStateAction<SuggestionsState>>
) => {
  const converters = useConverters();
  const { makeRequest } = useRequestService();
  return useCallback(
    debounce(async (tr: Transaction, allSuggestions: AiContentSuggestion[], requestId: string) => {
      const richContent = converters.fromPm(tr.doc.toJSON());
      const baseUrl =
        typeof location !== 'undefined' && location.hostname === 'editor.wix.com'
          ? 'https://editor.wix.com/_api/ricos-ai-assistant/v1/ricos-conversations'
          : 'https://www.wixapis.com/ricos/v1/ricos-conversations';
      const response = await makeRequest(`${baseUrl}/suggestions/list`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          richContent,
          suggestions: allSuggestions.map((suggestion: AiContentSuggestion) => {
            return {
              action: suggestion.action,
              prompt: suggestion.prompt,
              summary: suggestion.summary,
              position: 'RANGE',
              rangeDetails: {
                fromNodeId: suggestion.range.from,
                toNodeId: suggestion.range.to,
              },
            };
          }),
        }),
      });

      const responseJson = await response.json();

      const responseSuggestions: AiContentSuggestion[] =
        responseJson.suggestions?.map((suggestion: any) => ({
          id: generateId(),
          state: 'initial',
          range: {
            from: suggestion.rangeDetails?.fromNodeId || '',
            to: suggestion.rangeDetails?.toNodeId || '',
          },
          action: suggestion.action,
          prompt: suggestion.prompt,
          summary: suggestion.summary,
        })) ?? [];

      // only one suggestion per range!
      const suggestions = responseSuggestions
        .reduce((acc, suggestion) => {
          if (acc.find(s => s.range.from === suggestion.range.from)) {
            return acc;
          }

          return [...acc, suggestion];
        }, [] as AiContentSuggestion[])
        .slice(0, 3);

      setState(oldState => {
        if (oldState.type === 'loading' && oldState.requestId !== requestId) {
          return oldState;
        }

        if (!suggestions || suggestions.length === 0) {
          return oldState;
        }

        const contentSuggestions = oldState.suggestions;
        const suggestionsForSameRange = suggestions.map(s => {
          const existingSuggestion = contentSuggestions.find(
            ss =>
              (ss.range.from === s.range.from && ss.range.to === s.range.to) ||
              (ss.action === 'replace' &&
                ss.replacedWith?.from === s.range.from &&
                ss.replacedWith?.to === s.range.to)
          );
          if (existingSuggestion) {
            return {
              ...s,
              state: existingSuggestion.state === 'initial' ? 'loaded' : existingSuggestion.state,
            };
          }

          return s;
        });

        const dismissedButRelevant = oldState.suggestions.filter(
          s =>
            s.state === 'dismissed' &&
            !suggestionsForSameRange.some(
              ss => ss.range.from === s.range.from && ss.range.to === s.range.to
            )
        );

        const updatedSuggestions = [...suggestionsForSameRange, ...dismissedButRelevant];

        return {
          type: 'loaded',
          suggestions: updatedSuggestions,
          visible: oldState.visible,
          muted: oldState.muted,
        };
      });
    }, 5000),
    []
  );
};
