import * as Y from 'yjs';

import type { PmMarkJson, PmNodeJson } from './../pm-converters/types.js';
import type { PmTextNode } from './../_shared/pm-node-types.js';

// yjs doesn't export delta types
type YTextInsertOp = {
  insert: string;
  attributes?: Record<string, any>;
};

const isPmTextNode = (node: PmNodeJson): node is PmTextNode => node.type === 'text';

const convertNormalizedPmContentToYType = (node: PmTextNode[] | PmNodeJson) =>
  node instanceof Array ? convertPmTextNodesToYText(node) : convertPmNodeToYElement(node);

export const convertPmTextNodesToYText = (nodes: PmTextNode[]) => {
  const yXmlText = new Y.XmlText();
  const delta = nodes.map(node => ({
    insert: node.text,
    attributes: Object.fromEntries(node.marks?.map(({ type, attrs }) => [type, attrs]) ?? []),
  }));
  yXmlText.applyDelta(delta);
  return yXmlText;
};

export const convertPmNodeToYElement = (node: PmNodeJson) => {
  const yXmlElement = new Y.XmlElement(node.type);

  if (node.attrs) {
    Object.entries(node.attrs).forEach(([key, value]) => {
      if (value !== null && key !== 'ychange') {
        yXmlElement.setAttribute(key, value);
      }
    });
  }

  yXmlElement.insert(0, normalizePmNodeContent(node).map(convertNormalizedPmContentToYType));

  return yXmlElement;
};

/**
 * Rewrites an existing Y.XmlElement's attributes and children from a PM node while keeping the
 * element instance itself. Collab consumers (ySync, the yjs UndoManager, doc-attrs plugins) bind
 * to the element instance, and deleting it replicates through yjs — orphaning those bindings in
 * every peer. Yields the same attributes and children as convertPmNodeToYElement.
 */
export const rewriteYElementInPlace = (yXmlElement: Y.XmlElement, node: PmNodeJson) => {
  const nextAttrs = node.attrs ?? {};
  for (const key of Object.keys(yXmlElement.getAttributes())) {
    if (nextAttrs[key] === null || nextAttrs[key] === undefined) {
      yXmlElement.removeAttribute(key);
    }
  }
  Object.entries(nextAttrs).forEach(([key, value]) => {
    if (value !== null && key !== 'ychange') {
      yXmlElement.setAttribute(key, value);
    }
  });
  yXmlElement.delete(0, yXmlElement.length);
  yXmlElement.insert(0, normalizePmNodeContent(node).map(convertNormalizedPmContentToYType));
};

const normalizePmNodeContent = (pmNodeJson: PmNodeJson) => {
  const content = pmNodeJson.content ?? [];
  const normalizedContent: (PmTextNode[] | PmNodeJson)[] = [];

  // zip adjacent text nodes
  for (let i = 0; i < content.length; i++) {
    const node = content[i];

    if (isPmTextNode(node)) {
      const lastNormalizedItem =
        normalizedContent.length > 0 ? normalizedContent[normalizedContent.length - 1] : undefined;

      if (lastNormalizedItem && Array.isArray(lastNormalizedItem)) {
        lastNormalizedItem.push(node);
      } else {
        normalizedContent.push([node]);
      }
    } else {
      normalizedContent.push(node);
    }
  }

  return normalizedContent;
};

const convertYTextAttrsToPmMarks = (attributes?: Record<string, any>): PmMarkJson[] =>
  attributes
    ? Object.entries(attributes).map(([type, value]) => {
        const attrs = value !== null && typeof value === 'object' ? value : {};
        return { type, attrs };
      })
    : [];

export const convertYTextToPmTextNodes = (yXmlText: Y.XmlText): PmTextNode[] =>
  yXmlText.toDelta().map((op: YTextInsertOp) => {
    return {
      type: 'text' as const,
      text: op.insert,
      marks: convertYTextAttrsToPmMarks(op.attributes),
    };
  });

export const convertYElementToPmNode = (yXmlElement: Y.XmlElement): PmNodeJson => {
  const type = yXmlElement.nodeName;
  const pmAttrs = Object.fromEntries(Object.entries(yXmlElement.getAttributes()));
  const pmContent: PmNodeJson[] = [];

  for (const yChild of yXmlElement.toArray()) {
    if (yChild instanceof Y.XmlText) {
      pmContent.push(...convertYTextToPmTextNodes(yChild));
    } else if (yChild instanceof Y.XmlElement) {
      pmContent.push(convertYElementToPmNode(yChild));
    } else {
      throw new Error('Y.XmlFragment should only contain Y.XmlText and Y.XmlElement children');
    }
  }

  return {
    type,
    ...(Object.keys(pmAttrs).length > 0 ? { attrs: pmAttrs } : {}),
    ...(pmContent.length > 0 ? { content: pmContent } : {}),
  };
};
