import { RicosPluginToolbarNames } from './ricos-types/next/ricos-plugin-toolbar-names.js';
import type {
  InsertButtonId,
  QuickActionsConfig,
  ToolbarsConfig,
} from './ricos-types/next/toolbars-v2.js';
import { PluginNameToToolbarIdMap } from './ricos-types/plugin-name-to-toolbar-id-map.js';
import type { ToolbarSettings } from './ricos-types/ricos-types.js';
import { ToolbarType } from './ricos-types/toolbar-enums.js';
import type {
  FooterToolbarConfig,
  PlatformSettings,
  TextButtons,
  ToolbarSettingsFunctions,
} from './ricos-types/toolbar-settings-types.js';

/**
 * Translates the `@wix/ricos/next` toolbars config into the legacy
 * `toolbarSettings` shape consumed by the shared runtime.
 *
 * The runtime still uses the legacy pipeline (`ToolbarContextProvider`
 * + `getDefaultToolbarSettings` + `mergeToolbarSettings`). The adapter's job
 * is to produce a `ToolbarSettings` that expresses the same intent as the V2
 * input — collapsing platform-specific concepts that V2 intentionally hides
 * (MOBILE toolbar type, LINK decoration toolbar, etc.) into the low-level
 * toolbar types the runtime knows about.
 *
 * Design notes:
 * - Multiple V2 fields can map to the same legacy toolbar type (e.g. `footer.disabled`
 *   and `footer.pluginsToDisplayInToolbar` both touch legacy `FOOTER`). We aggregate
 *   per-toolbar entries into a single object before returning, because the existing
 *   `mergeToolbarSettings` picks only the first custom entry per `name`.
 * - `plugin.buttons` is wired through `filterButtons` on the legacy `PLUGIN` config
 *   (added alongside this adapter). The consumer's returned id order drives the
 *   rendered button order; unknown ids are dropped.
 */

/**
 * Runtime `filterItems` gets lowercase ids via `PluginNameToToolbarIdMap`
 * (e.g. `'image'`, `'link'`). V2 consumers compare against
 * `RicosPluginToolbarNames` which uses UPPERCASE JTD Node/Decoration types
 * (`'IMAGE'`, `'LINK'`). Build the inverse lookup so the adapter can surface
 * the id consumers expect.
 */
const TOOLBAR_ID_TO_V2_NAME: Record<string, string> = (() => {
  const map: Record<string, string> = {};
  for (const [name, toolbarId] of Object.entries(PluginNameToToolbarIdMap)) {
    const v2Value = (RicosPluginToolbarNames as Record<string, string>)[name];
    // First-wins: LINK and ANCHOR share the same runtime id ('link').
    // Prefer LINK since that's the primary consumer-facing decoration name.
    if (v2Value && !map[toolbarId]) {
      map[toolbarId] = v2Value;
    }
  }
  return map;
})();

const toV2Name = (runtimeId: string): string => TOOLBAR_ID_TO_V2_NAME[runtimeId] ?? runtimeId;

/**
 * Runtime ids (lowercase) for decoration plugin toolbars. These are what
 * `filterItems(item, nodeType)` receives when the currently-selected plugin
 * toolbar belongs to a decoration rather than a block node.
 */
const DECORATION_RUNTIME_IDS = new Set<string>([
  PluginNameToToolbarIdMap.LINK,
  PluginNameToToolbarIdMap.ANCHOR,
]);

const ALL_DISABLED: PlatformSettings<boolean> = {
  desktop: false,
  mobile: { ios: false, android: false },
};

/**
 * Resolve a V2 `buttons` field (array or callback) into a platform-specific
 * legacy `getButtons` output. The callback is invoked once per platform with
 * the platform-resolved `defaultButtons` — so the same filter/reorder logic
 * applies to desktop and mobile defaults naturally.
 */
const resolveButtonsFactory = <Id extends string>(
  buttons: Id[] | ((ctx: { defaultButtons: Id[] }) => Id[]) | undefined,
  desktopDefault: Id[],
  mobileDefault: Id[]
): (() => PlatformSettings<Id[]>) | undefined => {
  if (!buttons) {
    return undefined;
  }

  if (Array.isArray(buttons)) {
    const list = buttons as Id[];
    return () => ({ desktop: list, mobile: { ios: list, android: list } });
  }

  const cb = buttons as (ctx: { defaultButtons: Id[] }) => Id[];
  return () => {
    const desktop = cb({ defaultButtons: desktopDefault });
    const mobile = cb({ defaultButtons: mobileDefault });
    return { desktop, mobile: { ios: mobile, android: mobile } };
  };
};

/**
 * Flatten a legacy text-button list to a plain string[] — some desktop entries
 * are group objects (e.g. align dropdown) that don't participate in V2's id-only
 * `defaultButtons`. Those are skipped; the V2 callback operates on flat ids, and
 * the adapter hands the callback's output back unchanged (group entries that
 * the consumer wants to preserve can be re-added by name).
 */
const toTextButtonIds = (list: TextButtons['desktop'] | TextButtons['mobile']): string[] => {
  const src = (list ?? []) as readonly unknown[];
  return src.filter((b): b is string => typeof b === 'string');
};

type LegacyCtx = {
  textButtons?: TextButtons;
  pluginButtonNames?: string[];
};

/**
 * Builds the array of custom `ToolbarSettingsFunctions` from the V2 config.
 * Grouped per-toolbar-type so multiple V2 fields targeting the same legacy
 * toolbar collapse into a single entry.
 */
const buildGetToolbarSettings =
  (v2: ToolbarsConfig) =>
  (ctx: LegacyCtx): ToolbarSettingsFunctions[] => {
    const perToolbar = new Map<ToolbarType, Record<string, unknown>>();
    const at = (name: ToolbarType): Record<string, unknown> => {
      const existing = perToolbar.get(name);
      if (existing) {
        return existing;
      }
      const fresh = { name };
      perToolbar.set(name, fresh);
      return fresh;
    };

    // ── text ──────────────────────────────────────────────────────────────
    const text = v2.text;
    const textButtonsDefault = ctx.textButtons ?? { desktop: [], mobile: [] };
    const desktopDefaults = toTextButtonIds(textButtonsDefault.desktop);
    const mobileDefaults = toTextButtonIds(textButtonsDefault.mobile);

    // `disabled` controls *rendering* of the built-in text toolbar variants;
    // it doesn't define what buttons exist. Apply `buttons` and `customButtons`
    // independently so consumers like the wixel asset-header (which reads the
    // button registry through `useToolbarWixelProps` and renders its own UI)
    // still get the configured button set even when the rendered V2 toolbar
    // is suppressed.
    const textVariants = [
      ToolbarType.FORMATTING,
      ToolbarType.STATIC,
      ToolbarType.INLINE,
      ToolbarType.MOBILE,
    ] as const;
    const getButtons = resolveButtonsFactory<string>(
      text?.buttons,
      desktopDefaults,
      mobileDefaults
    );
    if (getButtons) {
      for (const name of textVariants) {
        at(name).getButtons = getButtons;
      }
    }
    if (text?.customButtons) {
      const platformMap = {
        desktop: text.customButtons,
        mobile: { ios: text.customButtons, android: text.customButtons },
      };
      for (const name of textVariants) {
        at(name).getTextPluginButtons = () => platformMap;
      }
    }
    if (text?.disabled === true) {
      for (const name of textVariants) {
        at(name).shouldCreate = () => ALL_DISABLED;
      }
    }

    // ── insert ────────────────────────────────────────────────────────────
    const insert = v2.insert;
    const insertDefaults = ctx.pluginButtonNames ?? [];

    if (insert?.plusButton?.disabled === true) {
      at(ToolbarType.SIDE).shouldCreate = () => ALL_DISABLED;
    }
    if (insert?.plusButton?.onTrigger) {
      const onTrigger = insert.plusButton.onTrigger;
      // Runtime passes `defaultTrigger` to SIDE.onClick (see `floating-add-plugin-menu.tsx`).
      // Legacy consumers that declared `onClick: () => void` still work — they just ignore
      // the arg.
      at(ToolbarType.SIDE).onClick = (defaultTrigger: () => void) => onTrigger(defaultTrigger);
    }

    if (insert?.footer?.disabled === true) {
      at(ToolbarType.FOOTER).shouldCreate = () => ALL_DISABLED;
    }
    if (insert?.footer?.pluginsToDisplayInToolbar) {
      const footerConfig: FooterToolbarConfig = {
        pluginsToDisplayInToolbar: insert.footer
          .pluginsToDisplayInToolbar as unknown as FooterToolbarConfig['pluginsToDisplayInToolbar'],
      };
      at(ToolbarType.FOOTER).footerToolbarConfig = footerConfig;
    }

    const insertGetButtons = resolveButtonsFactory<InsertButtonId>(
      insert?.buttons,
      insertDefaults as InsertButtonId[],
      insertDefaults as InsertButtonId[]
    );
    if (insertGetButtons) {
      at(ToolbarType.INSERT_PLUGIN).getButtons = insertGetButtons;
      // Footer reads from the same insert button list in legacy runtime.
      if (!at(ToolbarType.FOOTER).getButtons) {
        at(ToolbarType.FOOTER).getButtons = insertGetButtons;
      }
    }

    // ── plugin ────────────────────────────────────────────────────────────
    const plugin = v2.plugin;
    if (plugin?.disabled === true) {
      at(ToolbarType.PLUGIN).shouldCreate = () => ALL_DISABLED;
      at(ToolbarType.LINK).shouldCreate = () => ALL_DISABLED;
    }
    if (plugin?.buttons) {
      const buttonsCb = plugin.buttons;

      // Emit `filterButtons`: receive the full item list, call V2's callback
      // with ids, reassemble items in the returned order (unknown ids are
      // dropped). This gives consumers full filter + reorder power.
      //
      // `nodeType` from the runtime is a lowercase `PluginNameToToolbarIdMap`
      // value; surface the matching V2 value (Node_Type / Decoration_Type) so
      // consumer comparisons against `RicosPluginToolbarNames` line up.
      at(ToolbarType.PLUGIN).filterButtons = (
        items: { id: string }[],
        nodeType: string
      ): { id: string }[] => {
        const isDecoration = DECORATION_RUNTIME_IDS.has(nodeType);
        const v2Name = toV2Name(nodeType);
        const defaultIds = items.map(item => item.id);
        const v2Ctx = isDecoration
          ? ({
              type: 'decoration',
              defaultButtons: defaultIds,
              decoration: v2Name as never,
            } as const)
          : ({ type: 'node', defaultButtons: defaultIds, nodeType: v2Name as never } as const);
        const returned = buttonsCb(v2Ctx as never);
        const byId = new Map(items.map(item => [item.id, item]));
        return returned
          .map(id => byId.get(id))
          .filter((item): item is { id: string } => item !== undefined);
      };
    }

    // ── quickActions ──────────────────────────────────────────────────────
    const qa: QuickActionsConfig | undefined = v2.quickActions;
    if (qa) {
      if (qa.disabled === true) {
        at(ToolbarType.QUICK_ACTIONS).shouldCreate = () => ALL_DISABLED;
        at(ToolbarType.QUICK_ACTIONS).activateOnFloatingPlusButton = false;
      }
      if (qa.placeholder !== undefined) {
        at(ToolbarType.QUICK_ACTIONS).placeholder = qa.placeholder;
      }
    }

    return Array.from(perToolbar.values()) as ToolbarSettingsFunctions[];
  };

/**
 * Main entry point. Takes the V2 `toolbars` prop from next's `RicosEditorProps`
 * and produces the legacy `toolbarSettings` object the shared runtime expects.
 *
 * Returns `undefined` when no V2 config was provided — the runtime then uses
 * pure defaults (equivalent to not passing `toolbarSettings` at all).
 */
export const toolbarsV2ToLegacy = (v2: ToolbarsConfig | undefined): ToolbarSettings | undefined => {
  if (!v2) {
    return undefined;
  }

  const result: ToolbarSettings = {
    getToolbarSettings: buildGetToolbarSettings(v2),
  };

  if (v2.text?.mode === 'static') {
    result.useStaticTextToolbar = true;
    result.textToolbarContainer = v2.text.container;
    result.staticToolbarAlignment = v2.text.alignment;
  }

  return result;
};
