import { Link } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { ModalServiceContext, RicosContext } from './../../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem } from './../../../../ricos-types/index.js';
import { LINK_MODAL_ID } from './../../../../_shared/link-modal/constants.js';
import { ToolbarButton } from './../../../../_shared/toolbar-button/toolbar-button.js';

type Props = {
  toolbarItem: IToolbarItem;
  dataHook?: string;
};

export const LinkButton: FC<Props> = ({ toolbarItem, dataHook }) => {
  const { t } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);
  const isModalOpen = useModalState(getIsModalOpen(LINK_MODAL_ID));

  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);

  const onClick = () => {
    toolbarItem.commands.click({ referenceElement, modalService });
  };

  return (
    <ToolbarButton
      active={isModalOpen || toolbarItem.attributes.active}
      prefix={Link}
      tooltip={t(toolbarItem.presentation?.tooltip ?? 'TextLinkButton_Tooltip')}
      onClick={onClick}
      ref={setReferenceElement}
      dataHook={dataHook}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
