import { TIPTAP_SHAPE_TYPE } from './../../ricos-content/index.js';
import type { ExtensionProps, NodeConfig, RicosExtension } from './../../ricos-types/index.js';
import { createRicosNodeExtension } from './../../plugin-commons/index.js';
import type { TiptapAdapterServices } from './../../tiptap-editor/initialize-tiptap-adapter.js';

import { Shape } from './index.js';

export const shapeTiptapExtension = createRicosNodeExtension({
  type: 'react-node',
  name: TIPTAP_SHAPE_TYPE,
  groups: [
    {
      group: 'resizable',
      options: {
        lockAspectRatio: true,
        verticallyResizable: true,
        saveDimensions: true,
        expandToFullWidthOnOverdrag: true,
      },
    },
    'not-overtypable',
    'shortcuts-enabled',
  ],
  reconfigure: (
    config: NodeConfig,
    _extensions: RicosExtension[],
    _props: ExtensionProps,
    settings: Record<string, unknown>,
    services: TiptapAdapterServices
  ) => ({
    ...config,
    addOptions: () => ({
      services,
      ...settings,
    }),
  }),
  Component: Shape,
  createExtensionConfig() {
    return {
      name: this.name,
      /*
       * Priority should be higher than ricos-common-plugin list-item extension in order
       * to shortcuts to work
       */
      priority: 102,
      group:
        'block smartBlockCellContent layoutCellContent collapsibleListItemBodyContent tableCellContent',
      selectable: true,
      draggable: true,
      addAttributes: () => {
        return {
          shape: null,
          link: null,
          altText: null,
          containerData: null,
          styles: {
            default: null,
          },
          isLoading: {
            default: false,
          },
          dimensions: {
            default: null,
          },
        };
      },
    };
  },
});
