import { Code } from '@wix/wix-ui-icons-common/lazy';

import type { AddButton } from './../ricos-types/index.js';
import { Node_Type } from './../ricos-types/index.js';
import { INSERT_PLUGIN_BUTTONS, TOOLBARS } from './../editor-common/index.js';

import { INSERT_CODE_BLOCK_BUTTON } from './data-hooks.js';
import { CODE_BLOCK_TYPE } from './types.js';

export const toolbarsToAddIn: (TOOLBARS.MOBILE | TOOLBARS.SIDE | TOOLBARS.FOOTER)[] = [
  TOOLBARS.MOBILE,
  TOOLBARS.SIDE,
  TOOLBARS.FOOTER,
];

export const getAddButtons = (_config: $TSFixMe, _services: $TSFixMe): AddButton[] => {
  return [
    {
      id: Node_Type.CODE_BLOCK,
      icon: Code,
      label: INSERT_PLUGIN_BUTTONS.CODE_BLOCK,
      dataHook: INSERT_CODE_BLOCK_BUTTON,
      tooltip: 'TextCodeBlock_InsertButton_Tooltip',
      toolbars: toolbarsToAddIn,
      command: ({ publicCommands }) => {
        publicCommands.insertBlockWithBlankLines(CODE_BLOCK_TYPE, {});
        return true;
      },
      menuConfig: {
        tags: 'codeBlock_plugin_search_tags',
        group: 'advanced',
      },
    },
  ];
};
