import type { PluginConverters, PmConverters } from './../pm-converters/collect.js';
import { collectPmConverters } from './../pm-converters/collect.js';
import { commonPlugins } from './../ricos-common-plugins/index.js';
import { pluginAudio } from './../plugin-audio/editor.js';
import { pluginActionButton, pluginLinkButton } from './../plugin-button/editor.js';
import { pluginCard } from './../plugin-card/editor.js';
import { pluginCodeBlock } from './../plugin-code-block/editor.js';
import { pluginCollapsibleList } from './../plugin-collapsible-list/editor.js';
import { pluginDivider } from './../plugin-divider/editor.js';
import { pluginEmoji } from './../plugin-emoji/editor.js';
import { pluginFileUpload } from './../plugin-file-upload/editor.js';
import { pluginGallery } from './../plugin-gallery/editor.js';
import { pluginGiphy } from './../plugin-giphy/editor.js';
import { pluginHashtag } from './../plugin-hashtag/editor.js';
import { pluginHeadings } from './../plugin-headings/editor.js';
import { pluginHtml } from './../plugin-html/editor.js';
import { pluginImage } from './../plugin-image/editor.js';
import { pluginIndent } from './../plugin-indent/editor.js';
import { pluginLineSpacing } from './../plugin-line-spacing/editor.js';
import { pluginLinkPreview } from './../plugin-link-preview/editor.js';
import { pluginLink } from './../plugin-link/editor.js';
import { pluginMentions } from './../plugin-mentions/editor.js';
import { pluginShape } from './../plugin-shape/editor.js';
import { pluginSmartBlock } from './../plugin-smart-block/editor.js';
import { pluginPoll } from './../plugin-social-polls/editor.js';
import { pluginSpoiler } from './../plugin-spoiler/editor.js';
import { pluginTable } from './../plugin-table/editor.js';
import {
  pluginTextColor,
  pluginTextHighlight,
} from './../plugin-text-color/editor.js';
import { pluginToc } from './../plugin-toc/editor.js';
import { pluginVerticalEmbed } from './../plugin-vertical-embed/editor.js';
import { pluginVideo } from './../plugin-video/editor.js';

export const createConverters = (plugins: PluginConverters[]): PmConverters => {
  const allPlugins = collectPluginsWithDependencies([...commonPlugins({}, []), ...plugins]);
  return collectPmConverters([...new Set(allPlugins)]);
};

const collectPluginsWithDependencies = (plugins: PluginConverters[]): PluginConverters[] =>
  plugins.flatMap(plugin => [
    plugin,
    ...(plugin.dependencies ? collectPluginsWithDependencies(plugin.dependencies) : []),
  ]);

const collectAllRicosPlugins = (): PluginConverters[] => {
  const allPlugins = collectPluginsWithDependencies([
    ...commonPlugins({}, []),
    pluginAudio(),
    pluginActionButton(),
    pluginLinkButton(),
    pluginCard(),
    pluginCodeBlock(),
    pluginCollapsibleList(),
    pluginDivider(),
    pluginEmoji(),
    pluginFileUpload(),
    pluginGallery(),
    pluginGiphy(),
    pluginHashtag(),
    pluginHeadings(),
    pluginHtml(),
    pluginImage(),
    pluginShape(),
    pluginIndent(),
    pluginLineSpacing(),
    pluginLink(),
    pluginLinkPreview(),
    pluginMentions(),
    pluginPoll(),
    pluginSpoiler(),
    pluginTable(),
    pluginToc(),
    pluginTextColor(),
    pluginTextHighlight(),
    pluginVerticalEmbed(),
    pluginVideo(),
    pluginSmartBlock(),
  ]);

  return [...new Set(allPlugins)];
};

let allPmConverters: PmConverters | undefined;

export const getAllPmConverters = (): PmConverters => {
  if (!allPmConverters) {
    allPmConverters = createConverters(collectAllRicosPlugins());
  }

  return allPmConverters;
};

export type { PmConverters } from './../pm-converters/collect.js';
export type { PmJson, PmMarkJson, PmNodeJson } from './../pm-converters/types.js';
