import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import type { HashtagPluginViewerConfig } from './types.js';
import { HASHTAG_TYPE } from './types.js';
import { nodeViewDecorator } from './viewer/hashtag-decorator.js';

export type { HashtagPluginViewerConfig } from './types.js';

export const pluginHashtag: ViewerPluginCreator<HashtagPluginViewerConfig> = config => {
  const pluginConfig = { ...DEFAULTS.config, ...config };
  return {
    config: pluginConfig,
    type: HASHTAG_TYPE,
    nodeViewDecorators: [nodeViewDecorator],
  };
};
