import { Tooltip } from '@wix/design-system';
import React, {
  forwardRef,
  useContext,
  useEffect,
  useId,
  useImperativeHandle,
  useMemo,
  useState,
} from 'react';

import { RicosContext, ZIndexContext } from './../../ricos-context/index.js';
import { ListItemSelect } from './../../_shared/list-item-select/list-item-select.js';
import { RICOS_INERT_TOOLTIP_HOST } from './../../_shared/ricos-inert-tooltip-host.js';

import styles from '../statics/mention-list-scss.js';
import type { MentionListProps, MentionListRef } from '../types.js';
import { MentionAvatar } from './mention-avatar.js';

// Inherited from the hand-rolled list: a name longer than this used to get a tooltip, because the
// row is a fixed width and the name is clipped. It is a proxy for "is this truncated" rather than a
// measurement, which is why it is a round number — kept as-is so the swap changes no behaviour.
const ELLIPSIS_CHARACTER_LIMIT = 23;

const INERT_TOOLTIP_HOST_SELECTOR = `[data-hook="${RICOS_INERT_TOOLTIP_HOST}"]`;

/**
 * The `@mention` typeahead's option list.
 *
 * The container is a plain `div`, not a WDS `Box`: a listbox has to carry `dir` (RTL) and
 * `aria-activedescendant`, and `Box` forwards neither — it destructures a fixed prop list and
 * spreads everything else into its inline `style`, so both would silently become bogus style keys
 * rather than attributes. `Box` is layout only, and this element needs semantics.
 *
 * Rows are the shared `_shared/list-item-select` wrapper (real WDS since #10486). They are
 * deliberately **not** tabbable: tiptap's suggestion plugin owns the keyboard while the typeahead is
 * open and the caret stays in the document, so the list is navigated with `aria-activedescendant`
 * and never takes focus. `tabIndex={-1}` overrides the wrapper's default because rest props spread
 * last.
 */
export const MentionList = forwardRef<MentionListRef, MentionListProps>((props, ref) => {
  const { languageDir, portal } = useContext(RicosContext) || {};
  const zIndex = useContext(ZIndexContext)?.getZIndex('TOOLTIP');
  const optionIdPrefix = useId();

  const [selectedIndex, setSelectedIndex] = useState(0);

  // The single host `RicosPortal` renders, reused from `_shared/toolbar-button`: its stylesheet
  // makes everything inside non-hit-testable. That matters more here than on a toolbar button —
  // an overflow tooltip on a list row lands over the *next* row and would swallow its click (it
  // hung `image.spec.ts` for a full 90s budget on #10486). Absent outside an editor.
  const tooltipHost = useMemo(
    () => portal?.querySelector<HTMLElement>(INERT_TOOLTIP_HOST_SELECTOR) ?? undefined,
    [portal]
  );

  const selectItem = (index: number) => {
    if (props.items[index]) {
      props.command(props.items[index]);
    }
  };

  const upHandler = () => {
    setSelectedIndex((selectedIndex + props.items.length - 1) % props.items.length);
  };

  const downHandler = () => {
    setSelectedIndex((selectedIndex + 1) % props.items.length);
  };

  const enterHandler = () => {
    selectItem(selectedIndex);
  };

  useEffect(() => setSelectedIndex(0), [props.items]);

  useImperativeHandle(ref, () => ({
    onKeyDown: ({ event }) => {
      if (event.key === 'ArrowUp') {
        upHandler();
        return true;
      }

      if (event.key === 'ArrowDown') {
        downHandler();
        return true;
      }

      if (['Enter', 'Tab'].includes(event.key)) {
        enterHandler();
        return true;
      }

      return false;
    },
  }));

  const optionId = (index: number) => `${optionIdPrefix}option-${index}`;

  return props.items.length ? (
    <div
      dir={languageDir}
      className={styles.mention_list}
      role="listbox"
      aria-activedescendant={optionId(selectedIndex)}
    >
      {props.items.map((item, i) => {
        const isTruncated = item.name.length > ELLIPSIS_CHARACTER_LIMIT;

        return (
          <ListItemSelect
            key={i}
            id={optionId(i)}
            // The caret stays in the document; the list is never focused.
            tabIndex={-1}
            selected={i === selectedIndex}
            onMouseOver={() => setSelectedIndex(i)}
            onSelect={() => selectItem(i)}
            prefix={<MentionAvatar src={item?.avatar} alt={item.name} />}
            title={
              isTruncated ? (
                // Wrapping the title rather than the row: the row wrapper is a plain function
                // component and forwards no ref, which WDS `Tooltip` needs for its trigger. Both
                // `fixed` and `zIndex` only ship with the host — `fixed` turns off popper's
                // `preventOverflow`, whose boundary `appendTo` would otherwise make that host div.
                <Tooltip
                  content={item.name}
                  placement="top"
                  {...(tooltipHost ? { appendTo: tooltipHost, fixed: true, zIndex } : {})}
                >
                  <span>{item.name}</span>
                </Tooltip>
              ) : (
                item.name
              )
            }
          />
        );
      })}
    </div>
  ) : null;
});
