import { Visible } from '@wix/wix-ui-icons-common/lazy';

import type { TextButton } from './../ricos-types/index.js';
import { Decoration_Type } from './../ricos-types/index.js';
import { isAlwaysVisible } from './../_shared/resolvers/is-always-visible.js';
import { isNodeSelected } from './../_shared/resolvers/is-node-selected.js';
import { isSpoilerInText } from './../_shared/resolvers/is-spoiler-in-text.js';

import { TEXT_BUTTON_SPOILER } from './data-hooks.js';

export const getTextButtons = (): TextButton[] => {
  return [
    {
      id: Decoration_Type.SPOILER,
      type: 'toggle',
      presentation: {
        dataHook: TEXT_BUTTON_SPOILER,
        tooltip: 'Spoiler_Insert_Tooltip',
        icon: Visible,
      },
      attributes: {
        visible: isAlwaysVisible,
        active: isSpoilerInText,
        disabled: isNodeSelected,
      },
      command:
        ({ publicCommands }) =>
        () => {
          publicCommands.toggleInlineStyle('spoiler');
          return true;
        },
    },
  ];
};
