import { type ReferenceType, hide, offset, useFloating } from '@floating-ui/react-dom';
import React, { useContext, useEffect, useMemo, useState } from 'react';
import ReactDOM from 'react-dom';

import { EditorContext, RicosContext } from './../ricos-context/index.js';
import { Node_Type } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { useAnimationPausedAutoUpdate } from './../_shared/node-animation/use-animation-paused-auto-update.js';
import { findChildren } from './../tiptap/index.js';

import type { AiContentSuggestion, SuggestionComponentProps } from './types.js';

const SUGGESTION_OFFSET = 8;
const BUBBLE_DIMENSIONS = 32;
const SUGGESTION_OFFSET_MOBILE = 8;

type SuggestionPopoverProps = {
  suggestion: AiContentSuggestion;
  onClick: () => void;
  Component: React.ComponentType<SuggestionComponentProps>;
  getPortalElement: () => HTMLElement | null;
};

export const SuggestionPopover: React.FC<SuggestionPopoverProps> = ({
  suggestion,
  onClick,
  Component,
  getPortalElement,
}) => {
  const { adapter } = useContext(EditorContext);
  const portal = getPortalElement();
  const [minimized, setMinimized] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const { isMobile } = useContext(RicosContext);

  const referenceElementLineHeight = useMemo(() => {
    let parsedLineHeight = 24;
    try {
      const doc = adapter.tiptapEditor.state.doc;
      const fromNode = findChildren(doc, node => node.attrs.id === suggestion.range.from)[0];
      if (!fromNode) {
        return parsedLineHeight;
      }
      const fromDomNode = adapter.tiptapEditor.view.nodeDOM(fromNode.pos) as HTMLElement;
      if (fromNode.node.type.name === Node_Type.TABLE && fromDomNode?.firstChild) {
        parsedLineHeight = 90;
      } else if (fromDomNode) {
        parsedLineHeight = parseInt(
          window.getComputedStyle(fromDomNode).getPropertyValue('line-height')
        );
      }
    } catch (e: any) {
      // oxlint-disable-next-line no-console
      console.log('Failed to calculate line height', e);
    }

    return parsedLineHeight;
  }, []);

  const {
    x,
    y,
    isPositioned,
    refs: { setReference, setFloating },
    elements,
    update,
    strategy,
  } = useFloating({
    placement: 'left-start',
    strategy: portal ? 'fixed' : 'absolute',
    middleware: [
      hide({ strategy: 'referenceHidden' }),
      offset(({ elements, rects }) => {
        if (isMobile) {
          const editor = adapter.tiptapEditor.view.dom;
          const editorBoundingRect = editor.getBoundingClientRect();
          const refEl = elements.reference as Element;
          const refBoundingRect = refEl.getBoundingClientRect();

          const offset =
            editorBoundingRect.left === refBoundingRect.left
              ? 0
              : editorBoundingRect.left - refBoundingRect.left;

          return {
            mainAxis: rects.floating.width * -1 - SUGGESTION_OFFSET_MOBILE - offset,
            crossAxis: ((BUBBLE_DIMENSIONS - referenceElementLineHeight) * -1) / 2,
          };
        }

        const refEl = elements.reference as Element;
        const refForDimensions = refEl.querySelector(`[data-breakout="normal"]`) ?? refEl;
        const computedStyles = window.getComputedStyle(refForDimensions);
        const maybeRefPadding = parseInt(computedStyles.getPropertyValue('padding-inline-start'));
        const maybeRefMargin = parseInt(computedStyles.getPropertyValue('margin-inline-start'));
        const refMargin = isNaN(maybeRefMargin) ? 0 : maybeRefMargin;
        const refPadding = isNaN(maybeRefPadding) ? 0 : maybeRefPadding;
        const refSpacing = refMargin * -1 + refPadding;
        return {
          mainAxis:
            rects.floating.width * -1 + BUBBLE_DIMENSIONS + (refSpacing * -1 + SUGGESTION_OFFSET),
          crossAxis: ((BUBBLE_DIMENSIONS - referenceElementLineHeight) * -1) / 2,
        };
      }),
    ],
  });

  useAnimationPausedAutoUpdate({
    reference: elements.reference,
    floating: elements.floating,
    update,
  });

  const doc = adapter.tiptapEditor.state.doc;
  const fromNode = findChildren(doc, node => node.attrs.id === suggestion.range.from)[0];
  // nodeDOM may return a non-Element when the range is stale mid-re-render; guard vs a throw.
  const refDom = fromNode ? adapter.tiptapEditor.view.nodeDOM(fromNode.pos) : null;
  const referenceElement = refDom instanceof HTMLElement ? refDom : null;

  useEffect(() => {
    setReference(
      referenceElement?.querySelector(`[id="${suggestion.range.from}"]`) ??
        (referenceElement as ReferenceType)
    );
  }, [setReference, referenceElement]);

  const handleMouseEnter = () => {
    setIsHovered(true);
    setMinimized(false);
  };

  const handleMouseLeave = () => {
    setIsHovered(false);
    setMinimized(true);
  };

  const handleBlur = () => {
    !isHovered && setMinimized(true);
  };

  if (!referenceElement) {
    return null;
  }

  const content = (
    <div
      ref={ref => {
        setFloating(ref);
      }}
      style={{
        top: y ?? '',
        left: x ?? '',
        width: `${BUBBLE_DIMENSIONS}px`,
        height: `${BUBBLE_DIMENSIONS}px`,
        position: strategy,
        display: 'block',
        visibility: isPositioned ? 'visible' : 'hidden',
        scale: 'var(--reverse-zoom-ratio)',
        zIndex: 'var(--ricos-internal-suggestion-z-index)',
      }}
    >
      {/* oxlint-disable-next-line jsx-a11y/no-static-element-interactions */}
      <div
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
        }}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        onBlur={handleBlur}
      >
        <Component minimized={minimized} onClick={onClick} title={suggestion.summary} />
      </div>
    </div>
  );

  return portal ? ReactDOM.createPortal(content, portal) : content;
};
