import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { DEFAULTS } from './defaults.js';
import type { IndentPluginViewerConfig } from './types.js';
import { INDENT_TYPE } from './types.js';

export const pluginIndent: ViewerPluginCreator<IndentPluginViewerConfig> = config => {
  return {
    config: { ...DEFAULTS.config, ...config },
    type: INDENT_TYPE,
  };
};
