import { ChevronDownSmall } from '@wix/wix-ui-icons-common/lazy';
import React, { useContext, useState } from 'react';

import { EditorContext, RicosContext } from './../../../../ricos-context/index.js';
import { getIsModalOpen, useModalState } from './../../../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem } from './../../../../ricos-types/toolbar-types.js';
import { ToolbarButton } from './../../../../_shared/toolbar-button/toolbar-button.js';

export const AlignmentButton = ({
  toolbarItem,
  dataHook,
}: {
  toolbarItem: IToolbarItem;
  dataHook?: string;
}) => {
  const { t } = useContext(RicosContext);
  const { getPublicCommands } = useContext(EditorContext);
  const [referenceElement, setReferenceElement] = useState<HTMLButtonElement | null>(null);
  const publicCommands = getPublicCommands?.();
  const Icon = toolbarItem.presentation.getIcon({ publicCommands, t });
  const tooltip = t(toolbarItem.presentation?.tooltip);

  const isModalOpen = useModalState(getIsModalOpen('TextAlignment.modal'));

  return (
    <ToolbarButton
      ref={setReferenceElement}
      disabled={toolbarItem.attributes.disabled}
      active={isModalOpen}
      tooltip={tooltip}
      onClick={() => {
        toolbarItem.commands?.click({ referenceElement });
      }}
      prefix={Icon}
      suffix={ChevronDownSmall}
      dataHook={dataHook}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
