import React, { useCallback, useMemo } from 'react';

import { useConverters } from './../../pm-converters/context.js';
import type { ShapeNode } from './../../ricos-schema/next-schema/index.js';
import type { PluginProps } from './../../ricos-types/index.js';

import { ROOT } from '../utils/data-hooks.js';
import { Shape as ShapeViewer } from '../viewer/viewer-shape.js';

type Dimensions = {
  width: number;
  height: number;
};

export const Shape = ({ node, updateAttributes }: PluginProps) => {
  const converters = useConverters();

  const ricosNode = useMemo(() => {
    return converters.fromPmNode(node.toJSON()) as ShapeNode;
  }, [
    node.attrs.id,
    node.attrs.shape,
    node.attrs.containerData,
    node.attrs.styles,
    node.attrs.link,
    node.attrs.altText,
    converters,
  ]);

  const isLoading = node.attrs.isLoading as boolean | undefined;
  const dimensions = node.attrs.dimensions as Dimensions | undefined;

  const onShapeLoaded = useCallback(
    (newDimensions: { width: number; height: number }) => {
      updateAttributes({ dimensions: newDimensions });
    },
    [updateAttributes]
  );

  return ricosNode ? (
    <div draggable data-drag-handle data-hook={ROOT} style={{ lineHeight: 0 }}>
      <ShapeViewer
        node={ricosNode}
        isLoading={!!isLoading}
        dimensions={dimensions}
        onShapeLoaded={onShapeLoaded}
      />
    </div>
  ) : null;
};
