import type { MutableRefObject } from 'react';
import React, { Suspense, forwardRef, useCallback, useEffect, useMemo, useState } from 'react';

import type { RicosEditorProps } from './../ricos-common/index.js';
import { LINK_PREVIEW_TYPE } from './../ricos-content/index.js';
import { isCommonPluginOptions } from './/utils/is-editor-plugin.js';
import { RICOS_VERSION } from './../ricos-schema/next-schema/index.js';
import { resolveTheme } from './../ricos-styles/resolve-theme.js';
import { useBiHelpers } from './../_shared/bi-strategy/use-bi-helpers.js';
import { deepMerge } from './../_shared/deep-merge.js';
import { extractPluginsConfig } from './../_shared/extract-plugins-config.js';
import { fetchEmbedData } from './../_shared/fetch-embed-data.js';
import { hasPlugin } from './../_shared/has-plugin.js';
import { useSetRicosEditorApi } from './../_shared/ricos-editor-api-context/ricos-editor-api-context.js';
import { getImageUrl } from './../_shared/url-resolvers.js';
import { useIframeSandboxDomain } from './../_shared/use-iframe-sandbox-domain.js';
import { isSSR } from './../wix-rich-content-common/index.js';
import {
  DevContextProvider,
  shouldShowDebuggingInfo,
} from './../wix-rich-content-common/lib/dev-tools.js';
import {
  OverrideFullRicosEditorLazy,
  hasWixInsiderOverride,
  useOverridePluginsMap,
} from './../wix-rich-content-common/lib/overrides.js';
import { isiOS } from './../editor-common/index.js';

import { loadCSS } from './load-css.js';
import type { RicosEditorRef } from './ricos-editor-ref.js';
import { RicosErrorBoundary } from './tiptap/ricos-error-boundary.js';

const FullRicosEditorLazy = React.lazy(() => {
  loadCSS();
  return import(/* webpackChunkName: "ricos_FullRicosEditor" */ './tiptap/full-ricos-editor.js');
});

const LocaleResourceProviderLazy = React.lazy(
  () =>
    import(
      /* webpackChunkName: "ricos_LocaleResourceProvider" */ './RicosContext/locale-resource-provider.js'
    )
);

const renderMobileDevTools = () => {
  // @ts-ignore-next-line
  if (typeof window !== 'undefined' && !window.__RICOS_DEVTOOLS_MOBILE_HOOK__) {
    // @ts-ignore-next-line
    window.__RICOS_DEVTOOLS_MOBILE_HOOK__ = true;
    const cdnTag = document.createElement('script');
    cdnTag.src = '//cdn.jsdelivr.net/npm/eruda';
    cdnTag.onload = () => {
      // @ts-ignore-next-line
      eruda.init();
    };
    window.document.head.appendChild(cdnTag);
  }
};

export const RicosEditor = forwardRef<RicosEditorRef, RicosEditorProps & { jsdomMode?: boolean }>(
  (props, ref) => {
    const {
      biSettings,
      instance,
      wixClient,
      iframeSandboxDomain: explicitDomain,
      msid,
      theme,
      environment: explicitEnvironment,
      ...restProps
    } = props;

    // Lazy load BI helpers only when biSettings AND instance are provided
    const {
      helpers: biHelpers,
      biLogger,
      biLoadPromise,
    } = useBiHelpers({ instance, biSettings, msid });

    // Fire onOpenEditorSuccess once BI helpers finish loading.
    // The event-system subscription in mapBiCallbacksToSubscriptions cannot handle
    // this reliably because BI helpers load asynchronously and may not be ready
    // when the 'ricos.editor.instance.loaded' event fires during mount.
    useEffect(() => {
      biLoadPromise.then(callbacks => {
        callbacks.onOpenEditorSuccess?.(
          RICOS_VERSION,
          'INLINE' as any,
          restProps.content?.metadata?.id
        );
      });
    }, [biLoadPromise]);

    // Compute iframeSandboxDomain from instance if not explicitly provided
    const iframeSandboxDomain = useIframeSandboxDomain(explicitDomain, instance);

    // Resolve Wix theme strategy (liveSite/wixStyle/nativeStyle) and environment
    const isBmPlatform = typeof window !== 'undefined' && !!window?.ModuleRegistry;
    const environment = explicitEnvironment ?? (isBmPlatform ? 'businessManager' : 'liveSite');
    const resolvedTheme = useMemo(
      () => resolveTheme({ theme, environment, isMobile: restProps.isMobile }),
      [theme, environment, restProps.isMobile]
    );

    const editorPlugins = props.plugins;

    // Extract plugin type names to pass to FullRicosEditor (resolved behind the lazy boundary)
    const pluginTypes = useMemo(
      () =>
        (editorPlugins || [])
          .filter(opt => !isCommonPluginOptions(opt) && !('tiptapExtensions' in opt))
          .map(opt => opt.type),
      [editorPlugins]
    );
    const overridePluginsMap = useOverridePluginsMap();

    const extractedPluginConfig = useMemo(
      () => extractPluginsConfig(editorPlugins),
      [editorPlugins]
    );

    const linkPreviewConfig = useMemo(() => {
      if (instance && hasPlugin(LINK_PREVIEW_TYPE, editorPlugins)) {
        return { [LINK_PREVIEW_TYPE]: { fetchData: fetchEmbedData(instance) } };
      }
      return {};
    }, [instance, editorPlugins]);

    const pluginConfig = useMemo(
      () => deepMerge({}, extractedPluginConfig.config, linkPreviewConfig),
      [extractedPluginConfig, linkPreviewConfig]
    );

    const helpers = useMemo(() => ({ ...biHelpers, getImageUrl }), [biHelpers]);

    // Self-register into RicosEditorApiContext so descendants can read the
    // imperative API via useRicosEditorApi(). When no provider is mounted
    // upstream, setRicosEditorApi is the context's no-op default.
    const setRicosEditorApi = useSetRicosEditorApi();
    const [registeredApi, setRegisteredApi] = useState<RicosEditorRef | null>(null);
    const mergedRef = useCallback(
      (node: RicosEditorRef | null) => {
        setRegisteredApi(node);
        if (typeof ref === 'function') {
          ref(node);
        } else if (ref) {
          (ref as MutableRefObject<RicosEditorRef | null>).current = node;
        }
      },
      [ref]
    );
    useEffect(() => {
      setRicosEditorApi(registeredApi);
      return () => setRicosEditorApi(null);
    }, [registeredApi, setRicosEditorApi]);

    if (
      (restProps.debugMode?.includes('mobile') || restProps.debugMode?.includes('all')) &&
      restProps.isMobile
    ) {
      renderMobileDevTools();
    }

    const loadingPlaceholder = restProps.loadingPlaceholder || <div />;

    const Wrapper = shouldShowDebuggingInfo(restProps.debugMode?.includes('all'))
      ? DevContextProvider
      : React.Fragment;

    const editorProps = {
      ...restProps,
      pluginConfig,
      helpers,
      biLogger,
      wixClient,
      instance,
      plugins: restProps.plugins,
      iframeSandboxDomain,
      theme: resolvedTheme,
      environment,
    };

    return isSSR() ? (
      <div />
    ) : (
      <Wrapper>
        <RicosErrorBoundary onError={restProps.onError}>
          <Suspense fallback={loadingPlaceholder}>
            <LocaleResourceProviderLazy fallback={loadingPlaceholder} locale={restProps.locale}>
              {locale => t =>
                hasWixInsiderOverride ? (
                  overridePluginsMap ? (
                    <OverrideFullRicosEditorLazy
                      {...editorProps}
                      pluginsMap={overridePluginsMap}
                      locale={locale}
                      t={t}
                      ref={mergedRef}
                      platform={isiOS() ? 'macOs' : 'windows'}
                    />
                  ) : (
                    loadingPlaceholder
                  )
                ) : (
                  <FullRicosEditorLazy
                    {...editorProps}
                    pluginTypes={pluginTypes}
                    locale={locale}
                    t={t}
                    ref={mergedRef}
                    platform={isiOS() ? 'macOs' : 'windows'}
                  />
                )
              }
            </LocaleResourceProviderLazy>
          </Suspense>
        </RicosErrorBoundary>
      </Wrapper>
    );
  }
);
RicosEditor.displayName = 'RicosEditor';
