import {
  ANCHOR_TYPE,
  APP_EMBED_TYPE,
  AUDIO_TYPE,
  BLOCKQUOTE,
  CODE_BLOCK_TYPE,
  COLLAPSIBLE_LIST_TYPE,
  DIVIDER_TYPE,
  EMOJI_TYPE,
  FILE_UPLOAD_TYPE,
  GALLERY_TYPE,
  GIPHY_TYPE,
  HTML_TYPE,
  IMAGE_TYPE,
  LINK_BUTTON_TYPE,
  LINK_PREVIEW_TYPE,
  LINK_TYPE,
  MENTION_TYPE,
  POLL_TYPE,
  TABLE_TYPE,
  VIDEO_TYPE,
} from './../../ricos-content/index.js';
import { extract } from './../../ricos-content/lib/extract.js';
import { getDataFieldValue } from './../../ricos-content/TranslatableAPI/utils.js';
import type { RichContent } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Decoration_Type, Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';

const countByType = (obj: { type?: string }[]) =>
  obj.reduce<Record<string, number>>((acc, x) => {
    const key = `${x.type}`;
    acc[key] = (acc[key] ?? 0) + 1;
    return acc;
  }, {});

const TO_PLUGIN_TYPE: { [key in Node_Type]?: string } = {
  [Node_Type.DIVIDER]: DIVIDER_TYPE,
  [Node_Type.IMAGE]: IMAGE_TYPE,
  [Node_Type.GALLERY]: GALLERY_TYPE,
  [Node_Type.GIF]: GIPHY_TYPE,
  [Node_Type.HTML]: HTML_TYPE,
  [Node_Type.VIDEO]: VIDEO_TYPE,
  [Node_Type.FILE]: FILE_UPLOAD_TYPE,
  [Node_Type.POLL]: POLL_TYPE,
  [Node_Type.COLLAPSIBLE_LIST]: COLLAPSIBLE_LIST_TYPE,
  [Node_Type.TABLE]: TABLE_TYPE,
  [Node_Type.EMBED]: LINK_PREVIEW_TYPE,
  [Node_Type.LINK_PREVIEW]: LINK_PREVIEW_TYPE,
  [Node_Type.APP_EMBED]: APP_EMBED_TYPE,
  [Node_Type.AUDIO]: AUDIO_TYPE,
  [Node_Type.BUTTON]: LINK_BUTTON_TYPE,
  [Node_Type.CODE_BLOCK]: CODE_BLOCK_TYPE,
  [Node_Type.BLOCKQUOTE]: BLOCKQUOTE,
};

const headingLevelToTag = {
  1: 'header-one',
  2: 'header-two',
  3: 'header-three',
  4: 'header-four',
  5: 'header-five',
  6: 'header-six',
};

const DECORATION_TO_NODE_TYPE: { [key in Decoration_Type]?: string } = {
  [Decoration_Type.MENTION]: MENTION_TYPE,
  [Decoration_Type.LINK]: LINK_TYPE,
  [Decoration_Type.ANCHOR]: ANCHOR_TYPE,
};

const emojiRegex =
  /\u00a9|\u00ae|[\u2000-\u3300]|\ud83c[\ud000-\udfff]|\ud83d[\ud000-\udfff]|\ud83e[\ud000-\udfff]/g;

export function getContentSummary(content: RichContent) {
  const { nodes } = content;
  const plugins = extract(nodes ?? [])
    .filter(
      node =>
        ![
          Node_Type.PARAGRAPH,
          Node_Type.TEXT,
          Node_Type.UNRECOGNIZED,
          Node_Type.COLLAPSIBLE_ITEM,
          Node_Type.COLLAPSIBLE_ITEM_BODY,
          Node_Type.COLLAPSIBLE_ITEM_TITLE,
          Node_Type.TABLE_CELL,
          Node_Type.TABLE_ROW,
        ].includes(node.type)
    )
    .map(node => {
      const { type } = node;
      const data = getDataFieldValue(node);
      const details: { type?: string; data?: any } = {};
      const plugin_type =
        TO_PLUGIN_TYPE[type] ||
        (type === Node_Type.HEADING &&
          headingLevelToTag[(data as any)?.level as keyof typeof headingLevelToTag]);
      if (plugin_type) {
        details.type = plugin_type;
        if (data) {
          details.data = data;
        }
      }
      return details;
    })
    .filter(node => !!node.type)
    .get();
  const decorations = extract(nodes ?? [])
    .filter(node => {
      return !!node.textData?.decorations?.some(decoration =>
        [Decoration_Type.ANCHOR, Decoration_Type.LINK, Decoration_Type.MENTION].includes(
          decoration.type
        )
      );
    })
    .map(node => {
      const data = node.textData?.decorations?.find(
        decoration => DECORATION_TO_NODE_TYPE[decoration.type]
      );
      const details: { type?: string; data?: any } = {};
      const plugin_type = data?.type && DECORATION_TO_NODE_TYPE[data.type];
      if (plugin_type) {
        details.type = plugin_type;
        if (data) {
          details.data = getDataFieldValue(node);
        }
      }
      return details;
    })
    .filter(node => !!node.type)
    .get();
  const emoji = extract(nodes ?? [])
    .map(({ textData }) => textData?.text || '')
    .get()
    .reduce((acc, text) => {
      return acc + (text.match(emojiRegex) || []).length;
    }, 0);
  return {
    pluginsCount: {
      ...countByType(plugins),
      ...countByType(decorations),
      [EMOJI_TYPE]: emoji,
    },
    pluginsDetails: [...plugins, ...decorations] as { type: string; data: any }[],
  };
}
