import classNames from 'classnames';
import type { ReactNode } from 'react';
import React, { forwardRef, useContext } from 'react';
import ReactDOM from 'react-dom';

import type { RicosContext } from './../../ricos-context/index.js';
import { StylesContext } from './../../ricos-styles/index.js';
import type { TextDirection } from './../../ricos-types/index.js';
import { RICOS_INERT_TOOLTIP_HOST } from './../../_shared/ricos-inert-tooltip-host.js';
import { isSSR } from './../../wix-rich-content-common/index.js';

interface Props {
  className?: string;
  container?: HTMLElement;
  children?: ReactNode;
  languageDir?: TextDirection;
  zIndex?: number;
  // Can't use RicosContext directly due to circular deps
  environment?: React.ContextType<typeof RicosContext>['environment'];
}

const RicosPortalInner = forwardRef<HTMLDivElement, Props>((props, ref) => {
  const { portalCssVars, stylePreset } = useContext(StylesContext);

  return (
    <div
      dir={props?.languageDir}
      ref={ref}
      data-hook="ricos-portal"
      className={classNames(props?.className, stylePreset)}
      style={{
        ...portalCssVars,
        ...(props.environment === 'wixel' ? { pointerEvents: 'auto' } : {}),
      }}
    >
      {/* One per editor — only one tooltip shows at a time — and inside the portal, the element
          a host's `settingsStyles.modals` z-index custom properties are set on. Skipped when a
          `container` is given: that instance is the static toolbar's, inside a host's element,
          and is not the one published as `RicosContext.portal`. */}
      {!props.container && <div data-hook={RICOS_INERT_TOOLTIP_HOST} />}
      {props?.children}
    </div>
  );
});

export const RicosPortal = forwardRef<HTMLDivElement, Props>((props, ref) => {
  if (!isSSR()) {
    const container = props?.container ?? document?.body;
    return ReactDOM.createPortal(<RicosPortalInner {...props} ref={ref} />, container);
  }
  return <RicosPortalInner {...props} ref={ref} />;
});
