import { ANIMATION_TYPE } from './../ricos-content/index.js';
import type { ViewerPluginCreator } from './../ricos-types/index.js';

export interface AnimationPluginViewerConfig {
  type: 'animation';
}

/**
 * Strict opt-in: entrance-animation playback only runs when this plugin is
 * registered on the viewer. Absent, animated nodes render statically visible.
 */
export const pluginAnimationViewer: ViewerPluginCreator<AnimationPluginViewerConfig> = config => ({
  config: { type: 'animation' as const, ...config },
  type: ANIMATION_TYPE,
});
