import type React from 'react';

import type { RicosDocumentNode } from './../ricos-schema/next-schema/index.js';

export type AiContentSuggestion = {
  id: string;
  state: 'initial' | 'loading' | 'loaded' | 'completed' | 'dismissed';
  range: {
    from: string;
    to: string;
  };
  prompt: string;
  summary: string;
} & ({ action: 'insert' } | { action: 'replace'; replacedWith?: { from: string; to: string } });

export type AiSuggestionAction = {
  type: 'toggle-suggestions';
  visible: boolean;
};

export const AI_SUGGESTIONS = 'ai-suggestions';

export type SuggestionsState = (
  | {
      type: 'initial' | 'loaded';
    }
  | {
      type: 'loading';
      requestId: string;
    }
) & {
  visible: boolean;
  muted: boolean;
  suggestions: AiContentSuggestion[];
};

export type SuggestionComponentProps = {
  onClick: () => void;
  title: string;
  minimized: boolean;
};

export type AiSuggestionsPluginConfig = {
  initiallyVisible?: boolean;
  onStateChange?: (state: 'loading' | 'loaded') => void;
  SuggestionComponent?: React.ComponentType<SuggestionComponentProps>;
  getPortalElement?: () => HTMLElement | null;
  interceptAction?: (prompt: string, selection: RicosDocumentNode[]) => void;
};
