import { Box, Divider, SidePanel } from '@wix/design-system';
import React, { useContext, useMemo, useState } from 'react';

import { ModalServiceContext, RicosContext } from './../../ricos-context/index.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { deepEqual } from './../../_shared/deep-equal.js';
import { MIN_LINE_HEIGHT } from './../../_shared/line-spacing-utils.js';
import type { DiscardPayload } from './../../plugin-ai/discard-confirmation-modal/discard-confirmation-modal.js';
import {
  FooterActions,
  Panel,
  PanelHeader,
  useClickOutside,
  usePanelContainerElement,
} from './../../ui-components/index.js';
import { PLUGIN_SETTINGS_PANEL_DISCARD_MODAL } from './../../ui-components/settings-panel-discard-modal/consts.js';
import { SettingsPanelDiscardModal } from './../../ui-components/settings-panel-discard-modal/settings-panel-discard-modal.js';

import { LINE_SPACING_CUSTOM_SPACING_MODAL_ID } from '../consts.js';
import {
  AFTER_PARAGRAPH_INPUT,
  BEFORE_PARAGRAPH_INPUT,
  LINE_SPACING_INPUT,
  MODAL_ROOT,
} from '../data-hooks.js';
import { DEFAULT_LINE_SPACING } from '../defaults.js';
import type { LineSpacings } from '../types.js';
import classes from './custom-spacing-editor-modal-scss.js';
import { InputWithLabel } from './input-with-label/input-with-label.js';

type CustomSpacingEditorModalProps = {
  initialLineSpacing: LineSpacings;
  insertDecoration: (data: LineSpacings, options?: { shouldFocus?: boolean }) => void;
};

export const CustomSpacingEditorModal: React.FC<CustomSpacingEditorModalProps> = ({
  insertDecoration,
  initialLineSpacing,
}) => {
  const { t } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);
  const containerEl = usePanelContainerElement();

  const logBi = useBiNext({
    modalId: LINE_SPACING_CUSTOM_SPACING_MODAL_ID,
    pluginId: 'lineSpacing',
  });

  const [isDiscardModalOpen, setIsDiscardModalOpen] = React.useState(false);
  const [customLineSpacing, setCustomLineSpacing] = useState<LineSpacings>(() =>
    toCustomLineSpacing(initialLineSpacing)
  );

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: () => {
      tryClosingModal();
    },
    triggerOn: 'pointerdown',
    disable: isDiscardModalOpen,
  });

  const isDirty = useMemo(
    () => !deepEqual(customLineSpacing, toCustomLineSpacing(initialLineSpacing)),
    [customLineSpacing, initialLineSpacing]
  );

  const onSubmit = () => {
    insertDecoration(toLineSpacingDecoration(customLineSpacing));
    modalService.closeModal(LINE_SPACING_CUSTOM_SPACING_MODAL_ID);
  };

  const openDiscardModal = () => {
    return new Promise<DiscardPayload>(resolve => {
      modalService.openModal({
        id: PLUGIN_SETTINGS_PANEL_DISCARD_MODAL,
        Component: SettingsPanelDiscardModal,
        componentProps: {
          closeModal: confirmed => {
            modalService.closeModal(PLUGIN_SETTINGS_PANEL_DISCARD_MODAL);
            resolve(confirmed as DiscardPayload);
          },
        },
        layout: 'dialog',
        positioning: {
          referenceElement: containerEl,
        },
        disableArrowNavigation: true,
        onClickOutside: () => {},
      });
    });
  };

  const tryClosingModal = React.useCallback(async () => {
    if (!isDirty) {
      modalService.closeModal(LINE_SPACING_CUSTOM_SPACING_MODAL_ID);
      return false;
    }

    setIsDiscardModalOpen(true);
    const discardResult = await openDiscardModal();
    setIsDiscardModalOpen(false);

    if (discardResult.confirmed) {
      modalService.closeModal(LINE_SPACING_CUSTOM_SPACING_MODAL_ID);
      return true;
    }
  }, [openDiscardModal]);

  return (
    <Panel closeButtonProps={{ onClick: tryClosingModal }} dataHook={MODAL_ROOT}>
      <PanelHeader title={t('LineSpacing_customSpacing_Header')} />

      <Box direction="vertical" padding="SP3" gap="SP3" className={classes.content}>
        <Box direction="vertical" gap="SP3">
          <InputWithLabel
            label={t('LineSpacing_lineSpacing')}
            value={customLineSpacing['line-height']}
            onChange={value => {
              setCustomLineSpacing({ ...customLineSpacing, 'line-height': value });
              logBi({ dataHook: LINE_SPACING_INPUT, value });
            }}
            min={MIN_LINE_HEIGHT}
            max={100}
            dataHook={LINE_SPACING_INPUT}
          />
          <Divider />
          <Box direction="vertical" gap="SP4">
            <InputWithLabel
              label={t('LineSpacing_beforeParagraph')}
              value={customLineSpacing['padding-top']}
              onChange={value => {
                setCustomLineSpacing({ ...customLineSpacing, 'padding-top': value });
                logBi({ dataHook: BEFORE_PARAGRAPH_INPUT, value });
              }}
              min={0}
              max={250}
              dataHook={BEFORE_PARAGRAPH_INPUT}
            />
            <InputWithLabel
              label={t('LineSpacing_afterParagraph')}
              value={customLineSpacing['padding-bottom']}
              onChange={value => {
                setCustomLineSpacing({ ...customLineSpacing, 'padding-bottom': value });
                logBi({ dataHook: AFTER_PARAGRAPH_INPUT, value });
              }}
              min={0}
              max={250}
              dataHook={AFTER_PARAGRAPH_INPUT}
            />
          </Box>
        </Box>
      </Box>
      <SidePanel.Footer showDivider>
        <FooterActions
          onCancel={tryClosingModal}
          onSave={() => {
            onSubmit();
          }}
          logBi={logBi}
        />
      </SidePanel.Footer>
    </Panel>
  );
};

const isNumericValue = (value: string) => !isNaN(parseFloat(value));

const ensureNumericValue = (value: string, fallback: string) =>
  isNumericValue(value) ? value : fallback;

const toLineSpacingDecoration = (data: LineSpacings): LineSpacings => {
  return {
    'line-height': ensureNumericValue(data['line-height'], DEFAULT_LINE_SPACING['line-height']),
    'padding-bottom': `${ensureNumericValue(
      data['padding-bottom'],
      DEFAULT_LINE_SPACING['padding-bottom']
    )}px`,
    'padding-top': `${ensureNumericValue(
      data['padding-top'],
      DEFAULT_LINE_SPACING['padding-top']
    )}px`,
  };
};

const toCustomLineSpacing = (data: LineSpacings): LineSpacings => ({
  'line-height': data['line-height'] ?? '1.5',
  'padding-bottom': data['padding-bottom'].slice(0, -2) ?? '0',
  'padding-top': data['padding-top'].slice(0, -2) ?? '0',
});
