import { PluginKey } from 'prosemirror-state';

import { ReactRenderer } from './../../tiptap/index.js';
import type { Editor } from './../../tiptap/react/index.js';
import { Suggestion as TiptapSuggestion } from './../../tiptap/suggestion/index.js';
import {
  anchorToSelection,
  updateFloatingPosition,
} from './../../editor-common/Utils/floating-ui-utils.js';

import type { Mention, MentionListProps, MentionListRef } from '../types.js';
import { MentionList } from './mention-list.js';

export const Suggestion = (
  editor: Editor,
  {
    mentionTrigger,
    getMentions,
    visibleItemsBeforeOverflow,
    handleDropdownOpen,
    handleDropdownClose,
    supportWhitespace = true,
    zIndex,
  }: {
    mentionTrigger: string;
    getMentions: (query: string) => Promise<Mention[]>;
    visibleItemsBeforeOverflow: number;
    handleDropdownOpen?: () => void;
    handleDropdownClose?: () => void;
    supportWhitespace?: boolean;
    zIndex: number;
  }
) => {
  const shouldEndMentioningProcess = (query: string, items: Mention[]) => {
    //There is no way to programmatically end mentioning process
    //https://github.com/ueberdosis/tiptap/issues/823
    const names = items.map(item => item.name.toLowerCase());
    return !names.some(name => name.includes(query.toLowerCase()));
  };

  return TiptapSuggestion({
    editor,
    char: mentionTrigger,
    allowSpaces: supportWhitespace,
    pluginKey: new PluginKey('mention'),
    command: ({
      editor,
      range,
      props,
    }: {
      editor: Editor;
      range: { from: number; to: number };
      props: Mention;
    }) => {
      const { name, slug, id, type } = props;
      editor.chain().focus().insertMention({ name, slug, id, type }, range).run;
    },
    items: async ({ query }) => {
      const mentions = await getMentions(query);
      return mentions
        .map(mention => ({
          name: mention.name,
          slug: mention.slug,
          avatar: mention.avatar,
          id: mention.id,
          type: mention.type,
        }))
        .slice(0, visibleItemsBeforeOverflow);
    },
    render: () => {
      let cleanup: () => void;
      let renderer: ReactRenderer<
        MentionListRef,
        MentionListProps & React.RefAttributes<MentionListRef>
      >;

      return {
        onStart: props => {
          renderer = new ReactRenderer(MentionList, {
            editor,
            props,
          });

          const element = renderer.element as HTMLElement;
          element.setAttribute('dir', '');
          element.style.position = 'absolute';

          const portal = document.querySelector('[data-hook=ricos-portal]') ?? document.body;
          portal.appendChild(element);

          cleanup = anchorToSelection(editor, renderer, zIndex);

          if (handleDropdownOpen) {
            handleDropdownOpen();
          } else {
            updateFloatingPosition(props.editor, element, zIndex);
          }
        },

        onUpdate(props) {
          renderer.updateProps(props);

          if (!handleDropdownOpen) {
            updateFloatingPosition(props.editor, renderer.element as HTMLElement, zIndex);
          }
        },

        onKeyDown(props) {
          if (props.event.key === 'Escape') {
            // @ts-ignore $TSFixMe
            this.onExit?.();
            return true;
          }

          const { items, query } = renderer.props;
          if (
            ['Enter', 'Tab'].includes(props.event.key) &&
            shouldEndMentioningProcess(query, items)
          ) {
            // @ts-ignore $TSFixMe
            this.onExit?.();
            return false;
          }

          if (!handleDropdownClose) {
            return renderer.ref?.onKeyDown?.(props) ?? false;
          }
          return false;
        },

        onExit() {
          renderer?.destroy?.();
          cleanup?.();
          if (handleDropdownClose) {
            handleDropdownClose();
          } else {
            renderer.element.remove();
          }
        },
      };
    },
  });
};
