import React from 'react';

import type {
  EditorPluginCreator,
  ExtensionProps,
  RicosExtension,
  RicosExtensionConfig,
} from './../ricos-types/index.js';
import type { CommandProps } from './../tiptap/core/index.js';
import type { TiptapAdapterServices } from './../tiptap-editor/initialize-tiptap-adapter.js';
import { createRicosFunctionalExtension } from './../tiptap-extensions/index.js';

import { aiSuggestionsPluginKey } from './plugin-key.js';
import { SuggestionsGlobalComponent } from './suggestions-global-component.js';
import {
  AI_SUGGESTIONS,
  type AiSuggestionsPluginConfig,
  type SuggestionComponentProps,
} from './types.js';

declare module './../tiptap/core' {
  interface Commands<ReturnType> {
    aiSuggestions: {
      toggleSuggestions: (visible: boolean) => ReturnType;
    };
  }
}
export const pluginAiSuggestions: EditorPluginCreator<AiSuggestionsPluginConfig> = config => {
  const onStateChange = config?.onStateChange ?? (() => {});
  const SuggestionComponent =
    config?.SuggestionComponent ??
    ((() => (
      <div>Suggestion component not provided</div>
    )) as React.ComponentType<SuggestionComponentProps>);
  return {
    config: {
      onStateChange,
      initiallyVisible: !!config?.initiallyVisible,
      SuggestionComponent,
      getPortalElement: config?.getPortalElement ?? (() => null),
      interceptAction: config?.interceptAction,
    },
    type: AI_SUGGESTIONS,
    selectable: false,
    tiptapExtensions: [
      createRicosFunctionalExtension({
        name: 'AI_SUGGESTIONS',
        type: 'extension',
        groups: [],
        reconfigure: (
          config: RicosExtensionConfig,
          _extensions: RicosExtension[],
          _ricosProps: ExtensionProps,
          _settings: Record<string, unknown>,
          services: TiptapAdapterServices
        ) => {
          return {
            ...config,
            addOptions: () => {
              return { services };
            },
          };
        },

        createExtensionConfig() {
          return {
            name: 'AI_SUGGESTIONS',

            addCommands() {
              return {
                toggleSuggestions:
                  (visible: boolean) =>
                  ({ chain }: CommandProps) => {
                    const chainedAction = chain().setMeta(aiSuggestionsPluginKey, {
                      type: 'toggle-suggestions',
                      visible,
                    });

                    return chainedAction.run();
                  },
              };
            },
          };
        },
      }),
    ],
    GlobalComponent: SuggestionsGlobalComponent,
  };
};
