import { autoUpdate, computePosition, flip, shift } from '@floating-ui/react-dom';

import { posToDOMRect } from './../../tiptap/index.js';
import type { Editor, ReactRenderer } from './../../tiptap/react/index.js';

export const updateFloatingPosition = (
  editor: Editor,
  element: HTMLElement,
  zIndex: number = 9999
) => {
  const virtualElement = {
    getBoundingClientRect: () =>
      posToDOMRect(editor.view, editor.state.selection.from, editor.state.selection.to),
  };

  computePosition(virtualElement, element, {
    placement: 'bottom-start',
    strategy: 'absolute',
    middleware: [shift(), flip()],
  }).then(({ x, y, strategy }) => {
    element.style.width = 'max-content';
    element.style.position = strategy;
    element.style.left = `${x}px`;
    element.style.top = `${y}px`;
    element.style.zIndex = `${zIndex}`;
  });
};

export const anchorToSelection = (editor: Editor, renderer: ReactRenderer, zIndex?: number) => {
  const element = renderer.element as HTMLElement;
  return autoUpdate(
    {
      getBoundingClientRect: () =>
        posToDOMRect(editor.view, editor.state.selection.from, editor.state.selection.to),
      contextElement: editor.view.dom,
    },
    element,
    () => updateFloatingPosition(editor, element, zIndex)
  );
};
