/**
 * Type-erased runtime re-exports for @wix/ricos/next.
 *
 * Each value is cast to `any` so that API Extractor cannot follow the
 * original type chain (which references proto RichContent). The consuming
 * module (next.ts) re-casts them to the correct RicosDocument-based types.
 *
 * RicosEditor is wrapped to split onChange into edit-only onChange + onSelectionChange.
 *
 * @internal
 */
import React, { forwardRef, useCallback, useImperativeHandle, useMemo } from 'react';

import { RicosEditor as OriginalRicosEditor } from './ricos-editor/index.js';
import type {
  ButtonClickContext,
  DropdownOption,
  ExternalToolbarButton,
  ToolbarPropsResult,
} from './ricos-types/next/index.js';

import { toolbarsV2ToLegacy } from './next-toolbars-adapter.js';

// ━━━ V2 useToolbarProps transformation ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
// Lives here — not on the shared adapter — so the transformation code only
// ships in the /next bundle. Legacy /index consumers don't pay for it.

const legacyTypeFor = (type: 'text' | 'insert' | 'plugin' | 'auto' | 'quickActions') => {
  switch (type) {
    case 'text':
      return 'FORMATTING';
    case 'insert':
      return 'INSERT_PLUGIN';
    case 'plugin':
      return 'PLUGIN';
    case 'auto':
      return 'WIXEL';
    case 'quickActions':
      return 'QUICK_ACTIONS';
  }
};

type LegacyOption = {
  id: string;
  label?: string;
  text?: string;
  icon?: React.ComponentType;
  dataHook?: string;
};

// Option labels may arrive as `label` (most buttons) or `text` (some legacy
// stores); fall back to `id` last. `icon` and `dataHook` forward through
// untouched when present.
const toDropdownOptions = (src: readonly LegacyOption[]): DropdownOption[] =>
  src.map(o => ({
    id: o.id,
    label: o.label ?? o.text ?? o.id,
    ...(o.icon ? { icon: o.icon } : {}),
    ...(o.dataHook ? { dataHook: o.dataHook } : {}),
  }));

/**
 * Convert the legacy `Record<id, ToolbarButtonProps>` shape into the flat
 * discriminated-union array the V2 hook exposes. Separators become
 * `kind: 'separator'`; dropdowns with typed `componentProps` become
 * `DropdownButton`; consumer-registered components become `CustomButton`;
 * everything else becomes an `ActionButton`.
 */
const toExternalToolbarButtons = (
  legacyButtons: Record<string, any>,
  isMobile: boolean
): ExternalToolbarButton[] => {
  const out: ExternalToolbarButton[] = [];
  for (const [id, btn] of Object.entries(legacyButtons)) {
    if (!btn) {
      continue;
    }
    if (btn.type === 'separator') {
      out.push({ kind: 'separator', id });
      continue;
    }
    // Custom buttons surface the consumer's own component as-is. The legacy
    // adapter doesn't emit this shape yet; the branch is reserved so the
    // type contract is stable once emission wiring lands.
    if (btn.type === 'custom' && typeof btn.component === 'function') {
      out.push({ kind: 'custom', id, component: btn.component });
      continue;
    }
    const icon = btn.getIcon?.();
    if (!icon) {
      continue;
    }
    const label = btn.getLabel?.() ?? '';
    const tooltip = btn.tooltip ?? '';
    const isActive = btn.isActive?.() ?? false;
    const isDisabled = btn.isDisabled?.() ?? false;

    // Dropdowns carry their selectable items inside `componentProps`. Two
    // shapes in practice (cf. form-wixel/rich-text-actions.tsx):
    //   1. `{ dropdownOptions, onSelect, selectedId }` — heading, alignment:
    //      `onSelect(id)` applies the option directly.
    //   2. `{ options, onSelect }` — line spacing, text color:
    //      `onSelect(ctx)` returns an `(id) => void` closure.
    if (btn.type === 'dropdown' && btn.componentProps) {
      const cp = btn.componentProps;
      if (Array.isArray(cp.dropdownOptions) && typeof cp.onSelect === 'function') {
        out.push({
          kind: 'dropdown',
          id,
          label,
          tooltip,
          icon,
          isActive,
          isDisabled,
          options: toDropdownOptions(cp.dropdownOptions),
          selectedId: cp.selectedId,
          // `ctx` is accepted for type consistency but not forwarded — the
          // underlying legacy callbacks for this shape (heading, alignment,
          // font-size) apply the selection directly without positional UI.
          onSelect: (optionId: string, _ctx?: ButtonClickContext) => cp.onSelect(optionId),
        });
        continue;
      }
      if (Array.isArray(cp.options) && typeof cp.onSelect === 'function') {
        out.push({
          kind: 'dropdown',
          id,
          label,
          tooltip,
          icon,
          isActive,
          isDisabled,
          options: toDropdownOptions(cp.options),
          selectedId: cp.selectedId,
          onSelect: (optionId: string, ctx?: ButtonClickContext) => {
            const apply = cp.onSelect({
              referenceElement: ctx?.referenceElement,
              isMobile,
            });
            apply?.(optionId);
          },
        });
        continue;
      }
      // Fallthrough: unrecognised dropdown → plain action.
    }

    const legacyOnClick = btn.onClick;
    out.push({
      kind: 'action',
      id,
      label,
      tooltip,
      icon,
      isActive,
      isDisabled,
      onClick: (ctx?: ButtonClickContext) => legacyOnClick?.(ctx ?? {}),
      ...(Array.isArray(btn.tags) && btn.tags.length > 0 ? { tags: btn.tags } : {}),
    });
  }
  return out;
};

// `FORMATTING` and `PLUGIN` are the only legacy `toolbarType` values the
// adapter emits for the `'WIXEL'` query — other toolbar variants don't
// populate this field, so we only map these two and leave anything else as
// `undefined` (i.e. don't surface `resolved`).
const resolvedFromLegacyType = (legacyType: string | undefined): 'text' | 'plugin' | undefined => {
  if (legacyType === 'FORMATTING') {
    return 'text';
  }
  if (legacyType === 'PLUGIN') {
    return 'plugin';
  }
  return undefined;
};

/**
 * Hook body: call the adapter's legacy reactive `useToolbarProps` and
 * transform its output. Invoked from the ref Proxy's `get` trap — the Proxy
 * returns a closure that calls this, so React sees a single hook call per
 * consumer render.
 *
 * `resolved` is only populated for `type === 'auto'` — the explicit variants
 * already imply which toolbar the consumer is reading. This matches the
 * legacy `toolbarType` field returned by `useToolbarProps('WIXEL')`.
 */
const useToolbarPropsV2 = (
  adapter: any,
  type: 'text' | 'insert' | 'plugin' | 'auto' | 'quickActions',
  isMobile: boolean
): ToolbarPropsResult => {
  const legacy = adapter.useToolbarProps(legacyTypeFor(type));
  const buttons = toExternalToolbarButtons(legacy.buttons, isMobile);
  if (type !== 'auto') {
    return { buttons };
  }
  const resolved = resolvedFromLegacyType(legacy.toolbarType);
  return resolved ? { buttons, resolved } : { buttons };
};

/**
 * Wrapper around RicosEditor that:
 * - splits onChange into edit-only onChange + onSelectionChange
 * - translates the V2 `toolbars` prop into legacy `toolbarSettings`
 * - proxies the ref so /next consumers see `useToolbarProps` with the V2
 *   shape — the transformation above runs only when this wrapper is used,
 *   so the legacy entry point (which never imports this file) is unaffected
 */
export const RicosEditor: any = forwardRef((props: any, ref: any) => {
  const {
    onChange,
    onSelectionChange,
    initialContent,
    toolbars,
    isMobile: isMobileProp,
    ...rest
  } = props;

  const combinedOnChange = useCallback(
    (content: any, meta: any) => {
      if (meta.source === 'edit') {
        onChange?.(content);
      } else {
        onSelectionChange?.(content);
      }
    },
    [onChange, onSelectionChange]
  );

  const toolbarSettings = useMemo(() => toolbarsV2ToLegacy(toolbars), [toolbars]);

  // Forward-only proxy: everything on the adapter stays the same except
  // `useToolbarProps`, which is re-pointed at the V2 implementation above.
  const [inner, setInner] = React.useState<any>(null);
  const setInnerRef = useCallback((api: any) => setInner(api), []);
  useImperativeHandle(ref, () => {
    if (!inner) {
      return undefined;
    }
    // Stable function reference per `inner` instance — avoids creating a new
    // closure on every Proxy `get` access, which keeps React's hook-identity
    // tracking happy even if a consumer destructures the hook.
    //
    // The Proxy intercepts `useToolbarProps` for every consumer, including
    // legacy callers reaching through `window.RICOS.editorRef` (e.g. wixel's
    // add-panel calling `useToolbarProps(ToolbarType.QUICK_ACTIONS)`). For
    // those, run the legacy hook unmodified — the V2 transformation only
    // applies when the type is one of the V2 strings.
    const v2Hook = (type: any) => {
      if (
        type === 'text' ||
        type === 'insert' ||
        type === 'plugin' ||
        type === 'auto' ||
        type === 'quickActions'
      ) {
        return useToolbarPropsV2(inner, type, !!isMobileProp);
      }
      return inner.useToolbarProps(type);
    };
    return new Proxy(inner, {
      get(target, prop, receiver) {
        if (prop === 'useToolbarProps') {
          return v2Hook;
        }
        return Reflect.get(target, prop, receiver);
      },
    });
  }, [inner, isMobileProp]);

  return (
    <OriginalRicosEditor
      {...rest}
      isMobile={isMobileProp}
      content={initialContent}
      onChange={combinedOnChange}
      toolbarSettings={toolbarSettings}
      ref={setInnerRef}
    />
  );
});
