import type { AnimationPluginEditorConfig } from './editor.js';

/**
 * Cross-cutting opt-in plugin (no node type — animation applies to existing
 * nodes). Registering it makes the shared animation button visible on node
 * plugin toolbars by exposing the panel through PluginExports, and contributes
 * the formatting-toolbar animation button for text blocks (which never produce
 * the NodeSelection the plugin-toolbar button requires). The PM attribute
 * layer and converters live in core so documents with animations round-trip
 * losslessly even without this plugin.
 */
export const pluginAnimation = (
  config?: Omit<AnimationPluginEditorConfig, 'type'>
): AnimationPluginEditorConfig => ({
  type: 'animation',
  ...config,
});

export type { AnimationPluginEditorConfig } from './editor.js';
