import React, { useCallback, useContext, useEffect } from 'react';

import { useConverters } from './../pm-converters/context.js';
import { generateId } from './../ricos-content/index.js';
import { EditorContext, PluginsContext } from './../ricos-context/index.js';
import { aiRegionPluginKey } from './../_shared/ai-region-plugin-key.js';
import { getIsEditorEmpty } from './../_shared/get-is-editor-empty.js';
import type { Transaction } from './../tiptap/pm/state.js';
import { findAdjustedNodeById } from './../tiptap-editor/helpers/find-adjusted-node-by-id.js';

import { aiSuggestionsPluginKey } from './plugin-key.js';
import { SuggestionPopover } from './suggestion-popover.js';
import type {
  AiContentSuggestion,
  AiSuggestionAction,
  AiSuggestionsPluginConfig,
  SuggestionsState,
} from './types.js';
import { AI_SUGGESTIONS } from './types.js';
import { useSuggestionsRequest } from './use-suggestions-request.js';

export const SuggestionsGlobalComponent: React.FC = () => {
  const editorPlugins = useContext(PluginsContext);
  const pluginConfig = editorPlugins?.getConfig(AI_SUGGESTIONS) as AiSuggestionsPluginConfig;
  const [state, setState] = React.useState<SuggestionsState>(() => ({
    type: 'initial',
    visible: !!pluginConfig?.initiallyVisible,
    suggestions: [],
    muted: false,
  }));
  const { adapter } = useContext(EditorContext);
  const converters = useConverters();
  const getSuggestions = useSuggestionsRequest(setState);

  const handleContentChange = useCallback(
    ({ transaction: tr }: { transaction: Transaction }) => {
      const muteSuggestions = !!aiRegionPluginKey.getState(adapter.tiptapEditor.state)?.regionList
        ?.length;

      const action: AiSuggestionAction = tr.getMeta(aiSuggestionsPluginKey);
      if (action?.type === 'toggle-suggestions') {
        setState(s => ({ ...s, visible: action.visible }));
        return;
      }

      if (getIsEditorEmpty(tr.doc)) {
        setState(s => ({
          type: 'loaded',
          suggestions: [],
          visible: s.visible,
          muted: muteSuggestions,
        }));
        return;
      }

      if (
        (tr.docChanged || state.type === 'initial') &&
        !tr.getMeta('table-node-attrs-updated') &&
        !tr.getMeta('appendedTransaction')?.getMeta('table-node-attrs-updated')
      ) {
        const requestId = generateId();
        getSuggestions(tr, state.suggestions, requestId);

        setState(s => ({
          ...s,
          type: 'loading',
          requestId,
          muted: muteSuggestions,
        }));
        return;
      }

      setState(s => ({
        ...s,
        muted: muteSuggestions,
      }));
    },
    [state]
  );

  useEffect(() => {
    adapter.tiptapEditor.on('transaction', handleContentChange);

    return () => {
      adapter.tiptapEditor.off('transaction', handleContentChange);
    };
  }, [handleContentChange]);

  const onConfirm = (suggestion: AiContentSuggestion) => {
    const doc = adapter.tiptapEditor.state.doc;
    const fromNode = findAdjustedNodeById(doc, suggestion.range.from);
    const toNode = findAdjustedNodeById(doc, suggestion.range.to);
    const selection =
      fromNode && toNode ? doc.slice(fromNode.pos, toNode.pos + toNode.node.nodeSize) : null;
    const selectionDoc = selection ? (converters.fromPm(selection.toJSON()) as any) : { nodes: [] };

    setState(s => {
      return {
        ...s,
        suggestions: s.suggestions.map(sug =>
          sug.id === suggestion.id ? { ...sug, state: 'loading' } : sug
        ),
      };
    });

    const onDone = ({ type }: { type: 'done' | 'error' }) => {
      setState(s => {
        return {
          ...s,
          suggestions: s.suggestions.map(sug =>
            sug.id === suggestion.id
              ? { ...sug, state: type === 'done' ? 'completed' : 'loaded' }
              : sug
          ),
        };
      });
    };

    if (pluginConfig.interceptAction) {
      pluginConfig.interceptAction(suggestion.prompt, selectionDoc.nodes);
      onDone({ type: 'done' });
      return;
    }

    adapter.tiptapEditor.commands.triggerInlineAi({
      prompt: suggestion.prompt,
      selection: selectionDoc.nodes,
      onDone,
    });
  };

  return (
    <>
      {!state.muted &&
        state.visible &&
        state.suggestions
          .filter(suggestion => !['completed', 'dismissed', 'loading'].includes(suggestion.state))
          .map(suggestion => (
            <SuggestionPopover
              key={suggestion.id}
              suggestion={suggestion}
              onClick={() => onConfirm(suggestion)}
              Component={pluginConfig.SuggestionComponent!}
              getPortalElement={pluginConfig.getPortalElement!}
            />
          ))}
    </>
  );
};
