import React, { useContext } from 'react';

import { ModalServiceContext } from './../../ricos-context/index.js';
import { ShapeColorsModal as SharedShapeColorsModal } from './../../_shared/plugin-toolbar/shape-colors-modal.js';
import type { ShapeColorEntry } from './../../_shared/plugin-toolbar/shape-colors-modal.js';
import { PmNodeType } from './../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';

import { SHAPE_COLOR_PICKER_MODAL_ID, SHAPE_COLORS_MODAL_ID } from '../utils/consts.js';
import { ShapeColorPickerModal } from './shape-color-picker-modal.js';

export const ShapeColorsModal = ({ nodeId }: { nodeId: string }) => {
  const modalService = useContext(ModalServiceContext);
  const { pmNodeAttrs } = useNodeAttrs(nodeId, PmNodeType.SHAPE);
  const colorMap: Record<string, string> = pmNodeAttrs?.styles?.colors ?? {};

  const onClose = () => {
    modalService?.closeModal(SHAPE_COLORS_MODAL_ID);
    modalService?.closeModal(SHAPE_COLOR_PICKER_MODAL_ID);
  };

  const openColorPickerFor = (
    entry: ShapeColorEntry,
    containerEl: HTMLElement | null | undefined
  ) => {
    modalService.togglePluginPanel({
      id: SHAPE_COLOR_PICKER_MODAL_ID,
      Component: ShapeColorPickerModal,
      componentProps: {
        nodeId,
        originalColor: entry.originalColor,
        initialColor: entry.displayedColor,
        colorsModalElement: containerEl,
      },
      isMobile: false,
      positioning: {
        referenceElement: containerEl,
        placement: 'right',
      },
      type: undefined,
    });
  };

  return (
    <SharedShapeColorsModal
      colorMap={colorMap}
      onClose={onClose}
      isColorPickerOpen={() => !!modalService?.isModalOpen(SHAPE_COLOR_PICKER_MODAL_ID)}
      openColorPickerFor={openColorPickerFor}
      closeColorPicker={() => modalService?.closeModal(SHAPE_COLOR_PICKER_MODAL_ID)}
    />
  );
};
