import { Avatar } from '@wix/design-system';
import React from 'react';

import styles from '../statics/mention-list-scss.js';

type Props = {
  src?: string;
  alt: string;
};

/**
 * The mention row's 28px avatar. WDS `Avatar` covers both cases the hand-rolled version needed —
 * an image when the mention has one, initials derived from the name when it does not — which
 * replaces the 6KB base64 placeholder SVG that used to stand in for "no avatar".
 *
 * It also drops the last `#wix-rich-content-ui-components` barrel import in this plugin. That
 * barrel is what dragged WDS into eight viewer graphs before #10515, so a deep import (or, here,
 * no import at all) is the standing preference for anything a viewer can reach.
 */
export const MentionAvatar = ({ src, alt }: Props) => (
  <Avatar
    className={styles.avatar}
    size="size30"
    imgProps={src ? { src, alt } : undefined}
    name={alt}
  />
);
