import type { PmMarkConverter } from './../pm-converters/types.js';
import type { MentionData, MentionDecoration } from './../ricos-schema/next-schema/index.js';
import { Decoration_Type } from './../ricos-schema/next-schema/index.js';

export const mentionConverter: PmMarkConverter = {
  fromPm: {
    type: Decoration_Type.MENTION,
    convert: mark => {
      const { attrs = {} } = mark;
      return [
        {
          type: Decoration_Type.MENTION,
          mentionData: attrs as MentionData,
        },
      ];
    },
  },
  toPm: {
    type: Decoration_Type.MENTION,
    convert: decoration => {
      const { mentionData } = decoration as MentionDecoration;
      return {
        type: Decoration_Type.MENTION,
        attrs: mentionData,
      };
    },
  },
};
