import type { ViewerPluginCreator } from './../ricos-types/index.js';

import { nodeViewDecorator } from './node-view-decorator.js';
import type { FontFamilyPluginViewerConfig } from './types.js';
import { FONT_FAMILY_TYPE } from './types.js';

export const pluginFontFamily: ViewerPluginCreator<FontFamilyPluginViewerConfig> = (
  config = {}
) => {
  return {
    config,
    type: FONT_FAMILY_TYPE,
    nodeViewDecorators: [nodeViewDecorator(config.fallbackFontFamily)],
  };
};
