import { SHAPE_TYPE } from './../ricos-content/index.js';
import type { EditorPluginCreator } from './../ricos-types/index.js';
import { RicosPluginToolbarNames } from './../ricos-types/index.js';

import { shapeConverter } from './converter/shape-converter.js';
import { getAddButtons } from './editor/get-add-buttons.js';
import { getQuickActions } from './editor/get-quick-actions.js';
import { getToolbarButtons } from './editor/get-toolbar-buttons.js';
import { shapeTiptapExtension } from './tiptap/tiptap-shape-extension.js';

export const pluginShape: EditorPluginCreator = () => {
  return {
    config: {},
    type: SHAPE_TYPE,
    pmMarkConverters: [],
    pmNodeConverters: [shapeConverter],
    tiptapExtensions: [shapeTiptapExtension],
    toolbar: {
      names: [RicosPluginToolbarNames.SHAPE],
      getButtons: (config, services) => getToolbarButtons(config, services),
    },
    getAddButtons: (config, services) => getAddButtons(config, services),
    getQuickActions: ({ pluginServices, config }) => getQuickActions(config, pluginServices),
  };
};
