import React from 'react';

import type { HeadingType, TextBlockType, TextButton } from './../ricos-types/index.js';
import { Node_Type } from './../ricos-types/index.js';
import type { TextButtonCommand } from './../ricos-types/toolbar-types.js';
import { createTextButton } from './../_shared/create-text-button.js';
import { translateHeading } from './../_shared/headings-dropdown-utils.js';
import { getHeadingInSelection } from './../_shared/resolvers/get-heading-in-selection.js';
import { isAlwaysVisible } from './../_shared/resolvers/is-always-visible.js';
import { isNodeOrCaptionSelected } from './../_shared/resolvers/is-node-or-caption-selected.js';
import { isTextStylesMatchDocumentStylesResolver } from './../_shared/resolvers/is-text-styles-match-document-styles.js';
import { HeadingButtonSwitch } from './../toolbars-v3/components/buttons/HeadingButtonSwitch/heading-button-switch.js';

import { TEXT_BUTTON_HEADINGS } from './data-hooks.js';
import { getCurrentHeadingIcon } from './dropdown/get-current-headings-icon.js';
import HeadingsDropdownLazy from './dropdown/headings-dropdown-lazy.js';
import { DEFAULT_HEADERS_DROPDOWN_OPTIONS, HEADER_TYPE_MAP } from './dropdown/headings-dropdown.js';
import type { HeadingsPluginEditorConfig } from './types.js';

const HEADINGS_MODAL_ID = `${Node_Type.HEADING}.modal`;

export const getTextButtons = (config?: HeadingsPluginEditorConfig): TextButton[] => {
  const isCustomHeadings = !!config?.allowHeadingCustomization;

  const id = `${Node_Type.HEADING}.dropdown`;

  const attributes = {
    isStylesMatch: isTextStylesMatchDocumentStylesResolver,
    visible: isAlwaysVisible,
    selectedHeading: getHeadingInSelection,
    disabled: isNodeOrCaptionSelected,
  };

  const presentation: TextButton['presentation'] = {
    dataHook: TEXT_BUTTON_HEADINGS,
    tooltip: 'FormattingToolbar_TextStyleButton_Tooltip',
    getIcon: ({ publicCommands, t }) => {
      return getCurrentHeadingIcon(isCustomHeadings, publicCommands, t);
    },
    renderer: toolbarItem => <HeadingButtonSwitch toolbarItem={toolbarItem} />,
  };

  const command: TextButtonCommand<any> =
    ({ modalService: modals, referenceElement, isMobile }) =>
    () => {
      modals.isModalOpen(HEADINGS_MODAL_ID)
        ? modals.closeModal(HEADINGS_MODAL_ID)
        : modals.openModal({
            id: HEADINGS_MODAL_ID,
            Component: isCustomHeadings ? HeadingsDropdownLazy(216) : HeadingsDropdownLazy(143),
            componentProps: {},
            positioning: {
              placement: 'bottom',
              referenceElement,
            },
            layout: isMobile ? 'drawer' : referenceElement ? 'floating' : 'dialog',
            returnFocusToEditor: true,
          });

      return true;
    };

  return [
    isCustomHeadings
      ? {
          id,
          type: 'modal',
          presentation,
          attributes,
          command,
        }
      : createTextButton({
          id,
          type: 'dropdown',
          presentation: {
            ...presentation,
            id: HEADINGS_MODAL_ID,
            Component: HeadingsDropdownLazy(143),
            getComponentProps: ({ publicCommands, t, modals }) => {
              const selectedHeading = publicCommands.getCurrentHeading();

              return {
                dropdownOptions: DEFAULT_HEADERS_DROPDOWN_OPTIONS.map(heading => ({
                  id: HEADER_TYPE_MAP[heading],
                  dataHook: `headings-dropdown-option-${HEADER_TYPE_MAP[heading]}`,
                  label: translateHeading(heading, t),
                })),
                onSelect: (heading: HeadingType) => {
                  const selectedHeading = publicCommands.getCurrentHeading();
                  const shouldSetBlockType = selectedHeading !== heading;
                  shouldSetBlockType && publicCommands.setBlockType(heading as TextBlockType);
                },
                selectedId: selectedHeading as string,
                closeModal: () => modals.closeModal(HEADINGS_MODAL_ID),
              };
            },
          },
          command,
          attributes,
        }),
  ];
};
