import { definePmNodeConverter } from './../../pm-converters/types.js';
import { generateId, TIPTAP_SHAPE_TYPE } from './../../ricos-content/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';
import type { Link, PluginContainerData } from './../../ricos-schema/next-schema/index.js';
import { fromTiptapLinkConverter } from './../../_shared/link/link-converters.js';

import { RICOS_DEFAULTS } from '../utils/consts.js';

const isDefaultContainerData = (
  value: PluginContainerData | undefined,
  defaultValue: PluginContainerData
): boolean => {
  if (!value) {
    return true;
  }

  return JSON.stringify(value) === JSON.stringify(defaultValue);
};

export const shapeConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.SHAPE],
    convert: node => {
      const shapeData = node.shapeData;

      return {
        type: TIPTAP_SHAPE_TYPE,
        attrs: {
          id: node.id ?? generateId(),
          shape: shapeData.shape,
          containerData: shapeData.containerData || RICOS_DEFAULTS.containerData,
          styles: shapeData.styles,
          animation: shapeData.animation ?? null,
          link: shapeData.link ?? null,
          altText: shapeData.altText ?? null,
        },
      };
    },
  },
  fromPm: {
    types: [TIPTAP_SHAPE_TYPE],
    convert: pmNode => {
      if (pmNode.type !== TIPTAP_SHAPE_TYPE) {
        return undefined;
      }

      const { id, shape, containerData, styles, animation, link, altText } = pmNode.attrs || {};
      return {
        type: Node_Type.SHAPE,
        id: id ?? generateId(),
        nodes: [],
        shapeData: {
          shape,
          containerData: isDefaultContainerData(containerData, RICOS_DEFAULTS.containerData)
            ? undefined
            : containerData,
          styles: styles ?? undefined,
          ...(animation ? { animation } : {}),
          link: fromTiptapLinkConverter(link) as Link,
          ...(altText ? { altText } : {}),
        },
      };
    },
  },
});
