import * as Y from 'yjs';

import { getAllPmConverters } from './../converters/index.js';
import type { PmNodeJson } from './../pm-converters/types.js';
import type { RichContent } from './../ricos-schema/next-schema/index.js';
import { getEmptyContent } from './../editor-common/index.js';

import {
  convertPmNodeToYElement,
  convertYElementToPmNode,
  rewriteYElementInPlace,
} from './y-converters.js';

const transactMaybe = (yFragment: Y.XmlFragment, callback: () => void, origin?: any) => {
  if (yFragment.doc) {
    yFragment.doc.transact(() => {
      callback();
    }, origin);
  } else {
    callback();
  }
};

export const writeYXmlFragment = (
  yFragment: Y.XmlFragment,
  content?: RichContent | null,
  origin?: any
) => {
  const pmJson = getAllPmConverters().toPm(content ?? (getEmptyContent() as RichContent));

  transactMaybe(
    yFragment,
    () => {
      const root = yFragment.length > 0 ? yFragment.get(0) : null;
      if (root instanceof Y.XmlElement && root.nodeName === 'doc') {
        // Every collab binding (ySync, the yjs UndoManager, doc-attrs plugins) hangs off this
        // exact element instance, and a delete replicates through yjs — peers' editors silently
        // stop syncing and their undo dies. Rewrite in place so a full-content write stays an
        // ordinary observable update.
        rewriteYElementInPlace(root, pmJson as PmNodeJson);
        // Trailing siblings (e.g. two clients bootstrapping an empty fragment concurrently)
        // violate the single-<doc> invariant readYXmlFragment enforces. The old full wipe
        // self-healed that state; trim them here while keeping the bound root.
        if (yFragment.length > 1) {
          yFragment.delete(1, yFragment.length - 1);
        }
        return;
      }
      yFragment.delete(0, yFragment.length);
      yFragment.insert(0, [convertPmNodeToYElement(pmJson as PmNodeJson)]);
    },
    origin
  );
};

export const readYXmlFragment = (yFragment: Y.XmlFragment): RichContent => {
  const yChildren = yFragment.toArray();

  if (yChildren.length !== 1) {
    throw new Error('Y.XmlFragment should contain exactly one element');
  }

  const yDocElement = yChildren[0];

  if (!(yDocElement instanceof Y.XmlElement)) {
    throw new Error('Document root should be an Y.XmlElement');
  }

  if (yDocElement.nodeName !== 'doc') {
    throw new Error('Document root should be a "doc" element');
  }

  return getAllPmConverters().fromPm(
    convertYElementToPmNode(yDocElement)
  ) as unknown as RichContent;
};
