import type { SuggestionKeyDownProps, SuggestionProps } from './../tiptap/suggestion/index.js';

export const MENTION_TYPE = 'mention';

export interface MentionsPluginEditorConfig {
  type: 'mentions';
  mentionTrigger?: string;
  getMentions?: (searchQuery: string) => Promise<Mention[]>;
  onMentionClick?: (mention: Mention) => void;
  visibleItemsBeforeOverflow?: number;
  supportWhitespace?: boolean;
  popoverComponent?: React.ReactNode;
  handleDropdownOpen?: () => void;
  handleDropdownClose?: () => void;
  getMentionLink?: () => string;
  zIndex?: number;
}
export interface MentionsPluginViewerConfig {
  getMentions?: (searchQuery: string) => Promise<Mention[]>;
  onMentionClick?: (mention: Mention) => void;
  onMentionHover?: (mention: Mention, ref: React.RefObject<HTMLElement>) => void;
  visibleItemsBeforeOverflow?: number;
  getMentionLink?: () => string;
  zIndex?: number;
}

export type Mention = {
  name: string;
  slug?: string;
  id?: string;
  avatar?: string;
  /**
   * The kind of entity the mention refers to. Any value is accepted, and it's usually
   * used to mark a mention as a group mention (for example, `group`).
   * When empty, the mention refers to a member.
   */
  type?: string;
};

export type MentionListRef = {
  onKeyDown?: (props: SuggestionKeyDownProps) => boolean;
};

export interface MentionListProps extends SuggestionProps<Mention> {}
