import { SPOILER_TYPE } from '../types.js';

export const initSpoilersContentState = (contentState: $TSFixMe) => {
  let prevSpoilerStyle = '';
  const blocks = contentState.blocks.map((block: $TSFixMe) => {
    let isBlockContainSpoiler;
    const inlineStyleRanges = block?.inlineStyleRanges?.map((range: $TSFixMe) => {
      if (range.style === SPOILER_TYPE) {
        isBlockContainSpoiler = true;
        if (block.text.length === range.offset + range.length) {
          prevSpoilerStyle =
            range.offset !== 0 || prevSpoilerStyle === ''
              ? `SPOILER_${block.key}_${range.offset}_${range.offset + range.length}`
              : prevSpoilerStyle;
        }
        return {
          ...range,
          style:
            range.offset === 0 && prevSpoilerStyle !== ''
              ? prevSpoilerStyle
              : `SPOILER_${block.key}_${range.offset}_${range.offset + range.length}`,
        };
      }
      return { ...range };
    });

    if (!isBlockContainSpoiler) {
      prevSpoilerStyle = '';
    }

    return {
      ...block,
      inlineStyleRanges,
    };
  });

  return {
    ...contentState,
    blocks,
  };
};
