/**
 * Theme input for `RicosEditor` and `RicosViewer`. Values flow into CSS variables
 * consumed by every plugin, the toolbars, and the settings panels — prefer this
 * over wrapping Ricos with external CSS, because external CSS only reaches the
 * editable area, not the chrome. Pair `colorPalette` (broad colors) with
 * `customStyles` (per-element overrides) for full control.
 */
export interface RicosTheme {
  /**
   * Global color tokens shared across all plugins, toolbars, and settings panels.
   * @example
   * ```tsx
   * import { fromPlainText, pluginHashtag, RicosEditor } from '@wix/ricos';
   * import React from 'react';
   *
   * export default () => {
   *   // @essential-start
   *   return (
   *     <div style={{ background: '#C9C9C9' }}>
   *       <RicosEditor
   *         initialContent={fromPlainText('This is a #hashtag, see it has a unique color.')}
   *         placeholder="Type here!"
   *         theme={{
   *           colorPalette: {
   *             format: 'color',
   *             bgColor: '#0E092B',
   *             textColor: '#FFFFFF',
   *             accent1: '#D6FF00',
   *           },
   *         }}
   *         plugins={[pluginHashtag()]}
   *       />
   *     </div>
   *   );
   *   // @essential-end
   * };
   * ```
   */
  colorPalette?: RicosPalette;
  /** Typography tokens. `fontFamily` cascades to every text node unless a `customStyles.<element>.fontFamily` overrides it. */
  typography?: RicosTypography;
  /**
   * Per-element style overrides for headings, paragraphs, quotes, plugin cards, and the editor container itself.
   * @example
   * ```tsx
   * import { fromPlainText, RicosEditor } from '@wix/ricos';
   * import React from 'react';
   *
   * export default () => {
   *   // @essential-start
   *   const theme = {
   *     customStyles: {
   *       h2: {
   *         fontFamily: 'Times',
   *         fontSize: '26px',
   *         color: 'orange',
   *         fontStyle: 'italic',
   *         textDecoration: 'underline',
   *       },
   *       h3: {
   *         fontFamily: 'Tahoma',
   *         fontSize: '20px',
   *         color: 'purple',
   *         textDecoration: 'none',
   *       },
   *       quote: {
   *         lineHeight: '24px',
   *         fontWeight: 'bold',
   *         color: 'brown',
   *       },
   *     },
   *   };
   *
   *   return (
   *     <RicosEditor
   *       initialContent={fromPlainText('Apply heading 2 or 3 from the toolbar to see the styles.')}
   *       placeholder="Type here!"
   *       theme={theme}
   *     />
   *   );
   *   // @essential-end
   * };
   * ```
   */
  customStyles?: RicosCustomStyles;
  /** Style overrides for settings modals (z-index layering). Most fields are deprecated — only `modals` is supported going forward. */
  settingsStyles?: RicosSettingsStyles;
  /** React-Native-flavoured style overrides; only consumed when `useNativeStyles` is `true`. */
  nativeStyle?: RicosNativeStyles;
  /** When `true`, applies the Wix Studio default theme on top of the supplied values. */
  useWixStyles?: boolean;
  /** When `true`, switches the renderer to consume `nativeStyle` instead of CSS overrides — used by mobile builds. */
  useNativeStyles?: boolean;
  /**
   * Breakout layout: lets specific nodes flow beyond the content column to viewport edges.
   * `rule` is called once per node at layout time; return `'fullWidth'` for the chosen nodes
   * (typically images and galleries) and `'normal'` for everything else. `fullWidthPadding`
   * overrides `normalPadding` for the `'fullWidth'` case.
   */
  breakout?: {
    rule: ({ node }: { node: RicosDocumentNode }) => 'fullWidth' | 'normal';
    normalPadding: {
      start: CSSProperties['paddingInlineStart'];
      end: CSSProperties['paddingInlineEnd'];
    };
    fullWidthPadding?: {
      start: CSSProperties['paddingInlineStart'];
      end: CSSProperties['paddingInlineEnd'];
    };
  };
}

