export interface RicosEditorProps {
  // ── Editor-specific ────────────────────────────────────────────────────────
  /** Array of editor plugins to enable. Each plugin adds editing capabilities (e.g., image, video, table). */
  plugins?: EditorPluginOptions[];
  /** Fires only when document content changes (not on selection changes). */
  onChange?: OnContentChangeFunction;
  /** Fires when the selection/cursor position changes (including during edits). */
  onSelectionChange?: OnSelectionChangeFunction;
  /**
   * Placeholder text displayed when the editor is empty.
   * @example
   * ```tsx
   * import { RicosEditor } from '@wix/ricos';
   * import React from 'react';
   *
   * export default () => {
   *   // @essential-start
   *   return <RicosEditor placeholder={'Type here!'} />;
   *   // @essential-end
   * };
   * ```
   */
  placeholder?: string;
  /**
   * Toolbars configuration — controls the text formatting toolbar, insert
   * plugin toolbars, plugin context toolbars and the quick-actions menu.
   */
  toolbars?: ToolbarsConfig;
  /** Callback fired when the editor transitions between busy and idle states (e.g., during media uploads). */
  onBusyChange?: (isBusy: boolean) => void;
  /** Maximum number of text characters allowed in the editor. When the limit is reached, further text input is ignored and paste actions are canceled if the result would exceed the limit. */
  maxTextLength?: number;
  /** A React component rendered as a side block alongside the editor content. Receives the block `id` as a prop. */
  sideBlockComponent?: FC<{ id: string }>;
  /** Custom commands to register with the editor. */
  commands?: any[];
  /** Settings for undo/redo history. */
  historySettings?: HistorySettings;
  /** Callback fired when the editor finishes loading and is ready for interaction. */
  onLoad?: (editor: any) => void;
  /** Controls initial cursor/focus position when the editor mounts. */
  autofocus?: FocusPosition;
  /** HTML element or factory function that returns the container element for rendering editor popovers and modals. */
  container?: HTMLElement | (() => HTMLElement | null);
  /** Initial content for the editor. Only used during initialization — not a controlled value. */
  initialContent?: RicosDocument;
  /** Custom keyboard shortcuts to register with the editor. */
  keyboardShortcuts?: any[];
  /** The placeholder to be displayed while the editor is loading. */
  loadingPlaceholder?: React.ReactNode;
  /**
   * Controls focus behavior when tabbing into the editor:
   * - `'edit'`: (default) Immediately enables typing when editor receives keyboard focus.
   * - `'container'`: Shows focus ring but requires Enter/key press to start editing.
   * @defaultValue 'edit'
   */
  tabFocusBehavior?: 'edit' | 'container';
  /** Unified color manager for sharing custom colors across all plugins. */
  colorManager?: ColorPaletteManager;
  modalSettings?: ModalSettings;
  /** Pick media implementation used by media-related plugins (e.g., image, gallery). */
  pickMedia?: _PublicPickMedia;
  /** Visitor upload settings used by file-upload-capable plugins. */
  visitorUploads?: _VisitorUploads;
  /** Maximum file size limit (in bytes) for uploads. */
  fileUploadSizeLimit?: number;
  /** HTML attributes applied to the editor's content-editable element. */
  htmlAttributes?: {
    autoCapitalize?: string;
    spellCheck?: boolean;
    autoComplete?: string;
    autoCorrect?: string;
    tabIndex?: number;
    ariaLabel?: string;
  };

  // ── Common ─────────────────────────────────────────────────────────────────
  /** When `true`, renders in mobile-optimized mode. */
  isMobile?: boolean;
  /** Link settings applied globally to all linkable plugins. */
  generalLinkSettings?: GeneralLinkSettings;
  /** Two-letter locale code (e.g., `'en'`, `'he'`). Determines the language and text direction of modals and settings. */
  locale?: string;
  /** Locale for content, when different from UI locale. If not defined, `locale` is used. */
  localeContent?: string;
  /** Callback fired when an error occurs in a Ricos component. */
  onError?: (error: string) => void;
  /** Theme configuration for colors, fonts, and custom styles. */
  theme?: RicosTheme;
  /** Default text alignment direction. */
  textAlignment?: TextAlignment;
  /** Callback fired when an atomic block (plugin) receives focus. */
  onAtomicBlockFocus?: onAtomicBlockFocus;
  /** Domain used to render UGC source code in an isolated sandboxed iframe. */
  iframeSandboxDomain?: string;
  /** When `true`, wraps text around left/right-aligned plugins. */
  textWrap?: boolean;
  /** Debug mode flags for enabling development-time diagnostics. */
  debugMode?: DebugMode[];
  /**
   * Theme variant to apply:
   * - `'businessManager'`: BM theme is applied and cannot be overridden.
   * - `'liveSite'`: liveSite theme is applied and can be overridden via `theme`.
   * @default 'liveSite'
   */
  environment?: Environment;
  /**
   * Base URL of the site, used to resolve page-relative URLs.
   * Used by links, buttons, gallery items, and vertical embeds to construct full hrefs
   * from relative paths (e.g., `/my-page` → `https://example.com/my-site/my-page`).
   *
   * If not provided, fetched automatically from `/_api/ricos-site-pages/base-url`.
   *
   * @example 'https://www.example.com/my-site'
   */
  baseUrl?: string;
  /** Business intelligence configuration for analytics and tracking. */
  biSettings?: BISettings;
  /**
   * Authenticated `WixClient` from `@wix/sdk`. When provided, takes priority over
   * `instance` for authorizing every request the editor makes (media uploads,
   * link previews, etc.). Use this in headless apps where you own the React tree.
   */
  wixClient?: WixClient;
  /**
   * Per-session Wix instance token. Used when no `wixClient` is provided — Ricos
   * builds an internal client from it. Typically set by Wix-served host pages.
   */
  instance?: string;
  /**
   * Metasite ID. Scopes storage and CDN traffic to the owning site when no
   * `wixClient` is given.
   */
  msid?: string;
  /**
   * When `true`, normalises rich content via `normalizeRicosDocument` before
   * rendering. Set to `false` to skip normalisation when content is already
   * known to be valid.
   * @default true
   */
  shouldNormalizeRichContent?: boolean;
  /** Media-upload, capture, and resolution settings shared across media plugins. */
  mediaSettings?: MediaSettings;
  /** @deprecated Use `generalLinkSettings` instead. */
  linkSettings?: LinkSettings;
  /**
   * Keep the editor's DOM alive across a transient React unmount instead of
   * tearing it down and rebuilding it on remount. Lets the host preserve editor
   * state (and avoid flicker) when the editor is briefly unmounted/remounted.
   * @default false
   */
  preserveDomOnUnmount?: boolean;
  /** @deprecated Not used at runtime. */
  experiments?: AvailableExperiments;
}

